((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).en = window.CARDS_BY_LANG.en || {}).film = [{"name":"The Godfather","emoji":"🍊","meta":["crime drama","1972","Francis Ford Coppola"],"description":"The Sicilian Corleone family runs its empire in 1940s New York, and when the ageing don is forced out of action his youngest son takes over. Adapted from Mario Puzo's novel, it set the template for the gangster film and left its dialogue quoted everywhere.","fact":"The line \"I'm going to make him an offer he can't refuse\" is among the most famous ever spoken on screen.","wiki_en":"The Godfather"},{"name":"The Shawshank Redemption","emoji":"⛓️","meta":["drama","1994","Frank Darabont"],"description":"A banker wrongly convicted of murdering his wife is sent to a brutal prison, where a friendship with a fellow inmate keeps him standing. Adapted from a Stephen King novella, it has spent years at the top of the IMDb viewers' chart.","fact":"It flopped in cinemas, then became one of the most rewatched films of all time thanks to television reruns and home video.","wiki_en":"The Shawshank Redemption"},{"name":"Pulp Fiction","emoji":"💼","meta":["crime comedy","1994","Quentin Tarantino"],"description":"Several tangled stories about Los Angeles gangsters, a boxer and a pair of small-time robbers, told wildly out of order. The film became famous for its broken chronology, its brash dialogue and its soundtrack, and it put John Travolta back on the big screen.","fact":"Whatever glows inside the briefcase is never shown — the audience is left to imagine it.","wiki_en":"Pulp Fiction"},{"name":"Forrest Gump","emoji":"🍫","meta":["drama","1994","Robert Zemeckis"],"description":"A simple-hearted young man from Alabama keeps stumbling into the defining events of American history in the second half of the twentieth century. The film mixes innocent humour with nostalgia and became one of the most quoted in pop culture.","fact":"Forrest's line about a box of chocolates — you never know what you're going to get — turned into an everyday idiom.","wiki_en":"Forrest Gump"},{"name":"The Matrix","emoji":"💊","meta":["science fiction","1999","The Wachowskis"],"description":"A hacker discovers that the world he knows is a computer simulation and that real life looks nothing like it, then joins the uprising against the machines. The film revolutionised visual effects with bullet time and made long black leather coats a fashion.","fact":"The choice between the red pill and the blue pill became shorthand for choosing between a comfortable lie and an unpleasant truth.","wiki_en":"The Matrix"},{"name":"Fight Club","emoji":"🧼","meta":["drama","1999","David Fincher"],"description":"A nameless office worker worn down by insomnia and apathy meets a charismatic soap salesman, and together they start underground fighting clubs. Adapted from Chuck Palahniuk's novel, it disappointed critics at first and later became a cult film.","fact":"The first rule of Fight Club — you do not talk about Fight Club — became a catchphrase far beyond cinema.","wiki_en":"Fight Club"},{"name":"Inception","emoji":"🌀","meta":["science fiction","2010","Christopher Nolan"],"description":"A specialist in breaking into other people's dreams is hired not to steal an idea but to plant one, which means descending through several layers of sleep at once. The nested structure and the open ending kept audiences arguing for years.","fact":"The spinning top the hero keeps testing became the symbol of the film's ambiguity: everyone decides for themselves whether it falls.","wiki_en":"Inception"},{"name":"Interstellar","emoji":"🚀","meta":["science fiction","2014","Christopher Nolan"],"description":"With crops failing and humanity close to extinction, a former pilot leaves his daughter behind and flies through a wormhole in search of a habitable planet. The film is known for physicist Kip Thorne's advice and for its rendering of a black hole.","fact":"Because time slows near the black hole, one hour on a distant planet costs the crew years back on Earth.","wiki_en":"Interstellar (film)"},{"name":"The Dark Knight","emoji":"🦇","meta":["action","2008","Christopher Nolan"],"description":"Batman, Commissioner Gordon and district attorney Harvey Dent try to stop an anarchist criminal called the Joker, who refuses to play by any of Gotham's rules. The film recast the superhero movie as a bleak crime thriller and won over the critics.","fact":"Heath Ledger, who died before the premiere, received a posthumous Oscar for playing the Joker.","wiki_en":"The Dark Knight"},{"name":"The Lord of the Rings: The Fellowship of the Ring","emoji":"💍","meta":["fantasy","2001","Peter Jackson"],"description":"The hobbit Frodo is handed a dangerous errand — destroy the One Ring — and sets out across Middle-earth with a mismatched company. The first part of the trilogy astonished audiences with the scale of its New Zealand locations and its care for detail.","fact":"All three films in the trilogy were shot almost simultaneously over more than a year.","wiki_en":"The Lord of the Rings: The Fellowship of the Ring"},{"name":"Harry Potter and the Philosopher's Stone","emoji":"⚡","meta":["fantasy","2001","Chris Columbus"],"description":"An orphaned boy learns he is a wizard and goes off to study at Hogwarts, where he makes friends and uncovers a family secret. The first film in the franchise based on J. K. Rowling's books launched one of the highest-grossing series in cinema.","fact":"The filmmakers auditioned thousands of children across Britain for the three leading roles.","wiki_en":"Harry Potter and the Philosopher's Stone (film)"},{"name":"Star Wars: Episode IV – A New Hope","emoji":"⚔️","meta":["science fiction","1977","George Lucas"],"description":"A young farm boy from a desert planet is pulled into the rebels' war against the galactic Empire and learns what he was meant for. George Lucas's film transformed visual effects and sound design and launched one of the biggest franchises in cinema.","fact":"Almost nobody expected it to succeed, and distributors opened it on a limited number of prints.","wiki_en":"Star Wars (film)"},{"name":"Titanic","emoji":"🚢","meta":["romance","1997","James Cameron"],"description":"Aboard a luxury liner everyone believed unsinkable, a penniless artist and a young woman from high society fall in love while the ship steams towards disaster. For years afterwards it remained the highest-grossing film ever made.","fact":"Celine Dion's My Heart Will Go On became one of the most recognisable songs ever written for a film.","wiki_en":"Titanic (1997 film)"},{"name":"Avatar","emoji":"🌿","meta":["science fiction","2009","James Cameron"],"description":"A former marine pilots an engineered Na'vi body to scout resources on the moon Pandora and slowly falls for the culture of the people living there. The film impressed audiences with its use of 3D and motion capture, building a whole alien world.","fact":"It became the highest-grossing film in the world and held that record for many years.","wiki_en":"Avatar (2009 film)"},{"name":"Jurassic Park","emoji":"🦖","meta":["science fiction","1993","Steven Spielberg"],"description":"On a remote island, scientists use ancient DNA to bring dinosaurs back for a theme park, and when the security systems fail the guests are left alone with the predators. Spielberg's film was a breakthrough in computer imagery.","fact":"Some of the dinosaurs are full-size animatronic models rather than computer graphics.","wiki_en":"Jurassic Park (film)"},{"name":"Jaws","emoji":"🦈","meta":["thriller","1975","Steven Spielberg"],"description":"A small seaside resort is terrorised by a giant white shark, and the police chief heads out to sea with an oceanographer and a hunter to put an end to it. Spielberg's film is usually called the first true summer blockbuster.","fact":"The mechanical shark broke down constantly, so Spielberg kept it off screen longer than planned — which only made the film tenser.","wiki_en":"Jaws (film)"},{"name":"E.T. the Extra-Terrestrial","emoji":"🛸","meta":["science fiction","1982","Steven Spielberg"],"description":"A boy finds an alien stranded in his back garden and, hiding him from the adults, helps him call home and reach his ship. Spielberg's warm family story about friendship and growing up became one of the best-loved films about visitors from space.","fact":"The shot of the bicycle flying across the face of the moon is one of the most recognisable images in cinema.","wiki_en":"E.T. the Extra-Terrestrial"},{"name":"Raiders of the Lost Ark","emoji":"🤠","meta":["adventure","1981","Steven Spielberg"],"description":"The archaeologist and adventurer known as Indiana Jones races the Nazis to the biblical Ark of the Covenant and the supernatural power it holds. The film married the spirit of old adventure serials to state-of-the-art stunts and chases.","fact":"The famous scene in which the hero faces a swordsman was improvised on the spot because the leading actor was feeling unwell.","wiki_en":"Raiders of the Lost Ark"},{"name":"Back to the Future","emoji":"🚗","meta":["science fiction","1985","Robert Zemeckis"],"description":"A teenager driving a car rebuilt into a time machine is thrown from 1985 back to 1955, meets his parents as youngsters and nearly prevents his own birth. The film became the classic of the time-travel genre.","fact":"The time machine is a production DeLorean, recognisable by its doors that swing upwards.","wiki_en":"Back to the Future"},{"name":"Terminator 2: Judgment Day","emoji":"🤖","meta":["science fiction","1991","James Cameron"],"description":"The older model of terminator now protects a teenage boy from a newer, more advanced cyborg made of liquid metal and sent back to change the future. The sequel became famous for the then-unheard-of effects of its shape-shifting villain.","fact":"The line \"I'll be back\" from the first film stayed Arnold Schwarzenegger's trademark for decades.","wiki_en":"Terminator 2: Judgment Day"},{"name":"Alien","emoji":"👽","meta":["horror","1979","Ridley Scott"],"description":"The crew of a commercial spacecraft answers a distress call from an unknown planet and unwittingly carries a lethal alien predator aboard. Ridley Scott's film fused space fiction with the grammar of horror.","fact":"The xenomorph was designed by the Swiss artist H. R. Giger, known for his dark biomechanical style.","wiki_en":"Alien (film)"},{"name":"Blade Runner","emoji":"🌃","meta":["science fiction","1982","Ridley Scott"],"description":"In a grim future a detective hunts down runaway bioengineered replicants, all but indistinguishable from people, and begins to wonder about his own nature. Adapted from a Philip K. Dick novel, it fixed the visual canon of cyberpunk for decades.","fact":"It flopped on release and was only later reappraised as one of the great science fiction films of the twentieth century.","wiki_en":"Blade Runner"},{"name":"Die Hard","emoji":"🏢","meta":["action","1988","John McTiernan"],"description":"A New York cop is left alone against a gang of armed criminals who have seized a skyscraper during a Christmas party — with his wife inside. The film set the pattern for years of action movies: one man against a crew in a closed space.","fact":"The hero's cry of \"Yippee-ki-yay\" became one of the most recognisable lines in the action genre.","wiki_en":"Die Hard"},{"name":"Home Alone","emoji":"🎄","meta":["comedy","1990","Chris Columbus"],"description":"An eight-year-old is left behind by mistake when his family flies off to Europe for Christmas, and he has to defend the house on his own against two hapless burglars. The inventive booby traps made it one of the great Christmas films.","fact":"For more than two decades it remained the highest-grossing live-action comedy worldwide.","wiki_en":"Home Alone"},{"name":"Pretty Woman","emoji":"👠","meta":["romantic comedy","1990","Garry Marshall"],"description":"A rich businessman hires a woman off the street to accompany him through a week of business meetings, and real feeling unexpectedly grows between them. This modern Cinderella made Julia Roberts a star and became a romantic comedy landmark.","fact":"The script began as a bleak drama about life on the street and only turned into a romantic comedy with a happy ending after the studio reworked it.","wiki_en":"Pretty Woman"},{"name":"Dirty Dancing","emoji":"💃","meta":["musical romance","1987","Emile Ardolino"],"description":"At a summer resort a girl from a comfortable family falls for a dancer from a poorer world and secretly rehearses with him for a performance that matters. The film is remembered for its dance numbers and for (I've Had) The Time of My Life.","fact":"The final lift, the partner raised overhead, became one of the most parodied dance moves in cinema.","wiki_en":"Dirty Dancing"},{"name":"Ghost","emoji":"👻","meta":["romance","1990","Jerry Zucker"],"description":"A murdered man stays behind as a ghost and, with the help of a con-artist medium, tries to protect the woman he loves and uncover the truth about his own death. It blended the supernatural with a tender love story and gave cinema the pottery wheel scene.","fact":"Unchained Melody, heard in the famous clay scene, became a hit again a quarter of a century after The Righteous Brothers recorded it.","wiki_en":"Ghost (1990 film)"},{"name":"The Silence of the Lambs","emoji":"🦋","meta":["thriller","1991","Jonathan Demme"],"description":"A young FBI trainee consults an imprisoned cannibal psychiatrist, Hannibal Lecter, in order to track down another serial killer. It remains one of the very few thrillers ever to win the Oscar for best picture.","fact":"Anthony Hopkins is on screen as Lecter for barely fifteen minutes, and that was enough to win him the Oscar for best actor.","wiki_en":"The Silence of the Lambs (film)"},{"name":"Se7en","emoji":"📦","meta":["thriller","1995","David Fincher"],"description":"Two detectives, one about to retire and one just starting out, investigate a string of murders staged around the seven deadly sins. The endless rain and Fincher's unsparing direction made it the benchmark crime thriller of the 1990s.","fact":"The ending with the box became one of the most discussed and most parodied twists in the history of the thriller.","wiki_en":"Seven (1995 film)"},{"name":"The Green Mile","emoji":"🐭","meta":["drama","1999","Frank Darabont"],"description":"A guard on death row in a 1930s prison meets a condemned giant with an inexplicable gift for healing. Adapted from Stephen King, the film mixes prison drama with the supernatural and with questions about faith and justice.","fact":"The Stephen King novel behind the film was originally published in separate instalments, like a paperback serial.","wiki_en":"The Green Mile (film)"},{"name":"Schindler's List","emoji":"🕯️","meta":["historical drama","1993","Steven Spielberg"],"description":"During the Second World War the German businessman Oskar Schindler saves more than a thousand Polish Jews by taking them on as workers in his factory. Shot almost entirely in black and white, Spielberg's film is based on a true story.","fact":"Spielberg took no fee for the film and used its earnings to found an institute recording the testimony of Holocaust survivors.","wiki_en":"Schindler's List"},{"name":"Saving Private Ryan","emoji":"🪖","meta":["war drama","1998","Steven Spielberg"],"description":"After the Normandy landings a squad of American soldiers is ordered to find the last surviving brother of four and bring him home. The long assault on the beach that opens the film is considered one of the most realistic battle scenes ever shot.","fact":"The combat was so unsparing that some Second World War veterans were reported to have walked out of screenings.","wiki_en":"Saving Private Ryan"},{"name":"Gladiator","emoji":"⚔️","meta":["historical drama","2000","Ridley Scott"],"description":"A Roman general betrayed by the emperor's envious heir loses his family and his freedom, ends up fighting in the arena and quietly plots his revenge. Ridley Scott's film revived Hollywood's appetite for the sword-and-sandal epic.","fact":"The hero's introduction, \"My name is Maximus Decimus Meridius\", became one of the most recognisable lines in cinema.","wiki_en":"Gladiator (2000 film)"},{"name":"Braveheart","emoji":"🗡️","meta":["historical drama","1995","Mel Gibson"],"description":"The Scot William Wallace raises a rebellion against English rule after English soldiers kill his wife. A sweeping historical drama with vast battle scenes, it won Mel Gibson the Oscar for directing.","fact":"The tartan kilts in the film are an anachronism — plaids of that kind appeared long after the events shown.","wiki_en":"Braveheart"},{"name":"Léon: The Professional","emoji":"🌱","meta":["crime drama","1994","Luc Besson"],"description":"A solitary professional killer takes in a twelve-year-old girl whose family has been murdered by corrupt agents, and grows attached to her against his own rules. Luc Besson's film pairs a hard action thriller with a surprisingly tender story of friendship.","fact":"The houseplant the hitman carries everywhere and tends like his only friend became the emblem of the whole film.","wiki_en":"Léon: The Professional"},{"name":"The Fifth Element","emoji":"🚕","meta":["science fiction","1997","Luc Besson"],"description":"A cab driver in a futuristic twenty-third-century New York is suddenly drawn into saving the world alongside a mysterious young woman who embodies an ancient weapon against absolute evil. Luc Besson's bright visual style crossed comic-book design with space opera.","fact":"The costumes were designed by Jean Paul Gaultier, including the famous outfit of white bandages worn by Milla Jovovich.","wiki_en":"The Fifth Element"},{"name":"The Lion King","emoji":"🦁","meta":["animation","1994","Roger Allers, Rob Minkoff"],"description":"The cub Simba is meant to inherit his father's throne on the African savannah, but after a tragedy he blames himself for he flees the pride and returns years later to claim his place. Disney's film, with songs by Elton John, was among the biggest animated hits of its time.","fact":"The story echoes Shakespeare's Hamlet, down to the betrayal and the revenge for a murdered father.","wiki_en":"The Lion King"},{"name":"Toy Story","emoji":"🧸","meta":["animation","1995","John Lasseter"],"description":"Woody the cowboy, the boy Andy's favourite toy, takes the arrival of a flashy new space ranger called Buzz Lightyear badly, and slowly learns to share his owner's attention. Pixar's film was the first feature-length cartoon made entirely on computers.","fact":"On the computers of the day, rendering a single frame of the first fully computer-animated feature could take hours.","wiki_en":"Toy Story"},{"name":"Shrek","emoji":"🧅","meta":["animation","2001","Andrew Adamson, Vicky Jenson"],"description":"A grumpy green ogre who wants his swamp back to himself agrees to rescue a princess from a dragon-guarded tower in exchange for his land. The film parodies classic fairy tales and mixes good-natured humour with jokes aimed over the children's heads.","fact":"Shrek's line about ogres having layers, like onions, is the most quoted in the film.","wiki_en":"Shrek"},{"name":"Finding Nemo","emoji":"🐠","meta":["animation","2003","Andrew Stanton"],"description":"A clownfish named Marlin crosses the whole ocean to find his son Nemo, scooped up for an aquarium, facing every danger with the scatterbrained but kind-hearted Dory. Pixar's film became famous for its lifelike animation of the underwater world.","fact":"After the film came out, demand for pet clownfish rose sharply, which alarmed conservationists.","wiki_en":"Finding Nemo"},{"name":"WALL-E","emoji":"🤖","meta":["animation","2008","Andrew Stanton"],"description":"On an Earth abandoned under its own rubbish, a lone cleaning robot keeps working until he falls in love with a sleek new-generation robot sent down on a survey mission. The first third of the film has almost no dialogue and runs on expressive mime.","fact":"WALL-E's voice and sounds were created by Ben Burtt, the same sound designer who once built the \"speech\" of R2-D2.","wiki_en":"WALL-E"},{"name":"Up","emoji":"🎈","meta":["animation","2009","Pete Docter"],"description":"An elderly widower ties thousands of balloons to his house and sets off for the journey to South America he had dreamed of with his wife, only to find a young scout on board. Pixar's film is known for an opening that tells a whole marriage without a word.","fact":"Besides the animation award, the film earned a best picture Oscar nomination, a rarity for the genre.","wiki_en":"Up (2009 film)"},{"name":"Frozen","emoji":"❄️","meta":["animation","2013","Chris Buck, Jennifer Lee"],"description":"A princess whose touch freezes everything accidentally plunges her kingdom into endless winter and hides in the mountains, while her sister sets out to put things right. Disney made the bond between the sisters, rather than romantic love, the heart of the story.","fact":"The song Let It Go became a worldwide hit and was recorded in dozens of languages.","wiki_en":"Frozen (2013 film)"},{"name":"Spirited Away","emoji":"🐉","meta":["animation","2001","Hayao Miyazaki"],"description":"On the way to a new home with her parents, a girl slips into the world of spirits, where her parents are turned into pigs and she has to take a job at a magical bathhouse to save them. Hayao Miyazaki's film was the first anime to win an Oscar.","fact":"For many years it remained the highest-grossing film ever released in Japanese cinemas.","wiki_en":"Spirited Away"},{"name":"Pirates of the Caribbean: The Curse of the Black Pearl","emoji":"🏴‍☠️","meta":["adventure","2003","Gore Verbinski"],"description":"A blacksmith sets out to rescue the governor's kidnapped daughter with the eccentric pirate Jack Sparrow, whose ship is cursed and whose crew turns to skeletons in moonlight. Based on a Disneyland ride, it unexpectedly revived the pirate adventure.","fact":"Johnny Depp built much of Jack Sparrow on the mannerisms of the musician Keith Richards.","wiki_en":"Pirates of the Caribbean: The Curse of the Black Pearl"},{"name":"Spider-Man","emoji":"🕷️","meta":["superhero film","2002","Sam Raimi"],"description":"An ordinary schoolboy, Peter Parker, gains superpowers from the bite of a radioactive spider and, after his uncle is killed, decides to use them for the good of the city. Sam Raimi's film was one of the first genuine superhero blockbusters of the century.","fact":"Uncle Ben's line \"with great power comes great responsibility\" became the character's motto for decades.","wiki_en":"Spider-Man (2002 film)"},{"name":"Iron Man","emoji":"🦾","meta":["superhero film","2008","Jon Favreau"],"description":"A billionaire arms magnate taken prisoner builds an armoured suit to escape, and once home he keeps refining it in order to fight evil instead of selling weapons. The film opened the Marvel Cinematic Universe.","fact":"The scene after the credits, in which Nick Fury appears, started the tradition of stingers tying the Marvel films into one universe.","wiki_en":"Iron Man (2008 film)"},{"name":"The Avengers","emoji":"🛡️","meta":["superhero film","2012","Joss Whedon"],"description":"Earth's mightiest heroes — Iron Man, Thor, Captain America, the Hulk and the rest — join forces for the first time to stop an alien army invading New York. It was the first full-scale crossover of the Marvel Cinematic Universe.","fact":"Gathering heroes from separate franchises into a single film had barely been attempted on this scale before.","wiki_en":"The Avengers (2012 film)"},{"name":"Avengers: Endgame","emoji":"💎","meta":["superhero film","2019","Anthony Russo, Joe Russo"],"description":"After the catastrophe of the previous film, the surviving superheroes look for a way to undo the erasure of half of all life in the universe. The finale of Marvel's years-long saga became one of the highest-grossing films ever made.","fact":"For a time it was the highest-grossing film in the history of world cinema, overtaking Avatar.","wiki_en":"Avengers: Endgame"},{"name":"Joker","emoji":"🃏","meta":["drama","2019","Todd Phillips"],"description":"A failing clown-for-hire and aspiring comedian living with mental illness loses his grip on reality amid the indifference and cruelty of the Gotham around him. The film reimagined the origin of a classic villain as a bleak social drama.","fact":"Joaquin Phoenix lost a great deal of weight for the part, to give the character a gaunt, broken look.","wiki_en":"Joker (2019 film)"},{"name":"Deadpool","emoji":"🗡️","meta":["superhero comedy","2016","Tim Miller"],"description":"A former special forces soldier, made a test subject in an underground cancer cure, comes out with superpowers and a ruined face, and takes revenge behind the mask of a motormouth mercenary. The film stands out for breaking the fourth wall and for its black humour.","fact":"Ryan Reynolds pushed for the film for years, and the decisive moment was a leaked test reel that audiences loved.","wiki_en":"Deadpool (film)"},{"name":"Guardians of the Galaxy","emoji":"🌌","meta":["superhero film","2014","James Gunn"],"description":"A ragtag band of space outlaws — including a talking raccoon and a walking tree — is dragged into a fight over an artefact powerful enough to destroy whole planets. The film stood out for its retro soundtrack of 1970s hits.","fact":"The Awesome Mix of old hits the hero listens to became a chart success of its own on streaming services.","wiki_en":"Guardians of the Galaxy (film)"},{"name":"Mad Max: Fury Road","emoji":"🏜️","meta":["action","2015","George Miller"],"description":"In the scorched wasteland of a post-apocalyptic future, the runaway war captain Furiosa and a chance companion, Max, try to escape a tyrant in a war rig loaded with the women he kept. The near-feature-length car chase won the film wide critical praise.","fact":"Most of the stunts and vehicle crashes were staged for real, with almost no computer graphics.","wiki_en":"Mad Max: Fury Road"},{"name":"John Wick","emoji":"🐶","meta":["action","2014","Chad Stahelski"],"description":"A retired hitman goes back to his old trade after former associates kill the puppy his late wife left him and steal his car. The film is known for the inventive choreography of its gunfights and hand-to-hand combat, which set a new standard for the genre.","fact":"The fight scenes were staged by former stuntmen, which gave the shootouts a physical honesty unusual for Hollywood.","wiki_en":"John Wick (film)"},{"name":"Kill Bill: Vol. 1","emoji":"🟡","meta":["action","2003","Quentin Tarantino"],"description":"A former assassin who survived being shot at her own wedding draws up a list of her old colleagues from the Deadly Viper squad and works through it one by one. Tarantino blends Japanese samurai films, Hong Kong action and the spaghetti western.","fact":"The heroine's yellow tracksuit is a direct nod to the outfit Bruce Lee wore in Game of Death.","wiki_en":"Kill Bill: Volume 1"},{"name":"Django Unchained","emoji":"⛓️","meta":["western","2012","Quentin Tarantino"],"description":"A freed slave teams up with a German bounty hunter to find and rescue his wife, still held by a brutal plantation owner in the American South. Tarantino reworks the spaghetti western through the subject of slavery in antebellum America.","fact":"The title and part of the score nod to the 1966 Italian western Django.","wiki_en":"Django Unchained"},{"name":"Inglourious Basterds","emoji":"🎬","meta":["war drama","2009","Quentin Tarantino"],"description":"A squad of Jewish American soldiers hunts Nazi officers in occupied France, while the owner of a Paris cinema prepares her own revenge for her murdered family. Tarantino mixes alternate history with a love letter to the movies.","fact":"Both words in the title are deliberately misspelled, and the film never explains why.","wiki_en":"Inglourious Basterds"},{"name":"Once Upon a Time in Hollywood","emoji":"📺","meta":["tragicomedy","2019","Quentin Tarantino"],"description":"A fading television western star and his stunt double try to stay afloat in the fast-changing Hollywood of the late 1960s, next door to Sharon Tate's house. Tarantino's film rebuilds the Los Angeles of that era in loving detail.","fact":"The story is set in Los Angeles in 1969 and plays against the real tragedy of that summer.","wiki_en":"Once Upon a Time in Hollywood"},{"name":"The Wolf of Wall Street","emoji":"💰","meta":["biographical comedy","2013","Martin Scorsese"],"description":"The stockbroker Jordan Belfort builds a financial empire on fraud and hurtles into a world of unthinkable luxury, drugs and impunity. Based on a real memoir, the film is known for its relentless pace and its provocative humour.","fact":"Leonardo DiCaprio plays a real man, Jordan Belfort, who later turns up in a cameo in the film itself.","wiki_en":"The Wolf of Wall Street (2013 film)"},{"name":"Shutter Island","emoji":"🏝️","meta":["psychological thriller","2010","Martin Scorsese"],"description":"A US marshal investigates the disappearance of a patient from a psychiatric hospital on a remote island, and the further he gets the less reliable the reality around him looks. The adaptation of Dennis Lehane's novel is built as an atmospheric thriller.","fact":"Scorsese deliberately filled the film with visual and narrative clues that only make sense on a second viewing.","wiki_en":"Shutter Island (film)"},{"name":"The Departed","emoji":"🕵️","meta":["crime drama","2006","Martin Scorsese"],"description":"An undercover policeman infiltrates the Irish mob in Boston while one of the mob's men works as a mole inside the police, and each tries to expose the other before he is exposed himself. The film brought Martin Scorsese his first directing Oscar.","fact":"It is a remake of the Hong Kong thriller Infernal Affairs.","wiki_en":"The Departed"},{"name":"Goodfellas","emoji":"🔫","meta":["crime drama","1990","Martin Scorsese"],"description":"The rise and fall of a small-time gangster who dreamed from boyhood of belonging to the Italian-American mafia of New York and worked his way from petty theft to serious crime. The film is based on a true life story and famous for its headlong editing.","fact":"The celebrated long take walking through the restaurant kitchen was shot in a single unbroken pass.","wiki_en":"Goodfellas"},{"name":"Taxi Driver","emoji":"🚕","meta":["psychological drama","1976","Martin Scorsese"],"description":"A lonely Vietnam veteran drives a night cab through a crime-ridden New York and, drifting further from everyone around him, works up a plan to cleanse the city by force. It became one of American cinema's defining portraits of urban isolation.","fact":"The score is by Bernard Herrmann, Hitchcock's long-time collaborator; it was his last film, and the picture is dedicated to his memory.","wiki_en":"Taxi Driver"},{"name":"Scarface","emoji":"🌎","meta":["crime drama","1983","Brian De Palma"],"description":"The Cuban émigré Tony Montana arrives in Miami with nothing and builds a drug empire, climbing the bloody ladder of the criminal world. A remake of a 1932 film, it became the cult story of the American dream turned inside out.","fact":"The words \"The world is yours\", which the hero sees on a passing airship, became the motto of the whole story.","wiki_en":"Scarface (1983 film)"},{"name":"The Big Lebowski","emoji":"🎳","meta":["comedy","1998","Ethan Coen, Joel Coen"],"description":"A lazy bowling enthusiast known as the Dude is mistaken for a millionaire with the same name and pulled into an absurd tale of kidnapping and ransom. The Coen brothers' eccentric comedy passed almost unnoticed at first and grew a huge cult following.","fact":"Fans hold an annual Lebowski Fest, complete with bowling and costumes from the film.","wiki_en":"The Big Lebowski"},{"name":"No Country for Old Men","emoji":"🪙","meta":["thriller","2007","Ethan Coen, Joel Coen"],"description":"A hunter who stumbles on the money from a drug deal gone wrong tries to disappear from the merciless killer tracking him across the Texas scrub. Adapted from Cormac McCarthy's novel, it won the Coen brothers the Oscar for best picture.","fact":"The killer's weapon of choice is a captive bolt pistol for slaughtering cattle, a startling thing to find in a crime thriller.","wiki_en":"No Country for Old Men"},{"name":"American Beauty","emoji":"🌹","meta":["drama","1999","Sam Mendes"],"description":"A middle-aged man disillusioned with his job and his marriage hits a crisis, falls for his daughter's friend and decides to blow up his life in defiance of suburban convention. The film is known for its visual symbolism, above all the scattered rose petals.","fact":"A plastic bag drifting on the wind in one scene became one of the most discussed and most parodied images in the film.","wiki_en":"American Beauty (1999 film)"},{"name":"The Sixth Sense","emoji":"👦","meta":["supernatural thriller","1999","M. Night Shyamalan"],"description":"A child psychologist tries to help a boy who says he sees dead people, and step by step they both reach a truth that changes the whole story. The film became famous for one of the most unexpected final twists in cinema.","fact":"The boy's line \"I see dead people\" became one of the most recognisable and most parodied in the movies.","wiki_en":"The Sixth Sense"},{"name":"A Beautiful Mind","emoji":"🧮","meta":["biographical drama","2001","Ron Howard"],"description":"The gifted mathematician John Nash makes breakthrough after breakthrough while fighting a worsening schizophrenia that warps his sense of what is real. The film is based on the life of a real Nobel laureate in economics.","fact":"It won the Oscar for best picture, and Jennifer Connelly won for best supporting actress.","wiki_en":"A Beautiful Mind (film)"},{"name":"Catch Me If You Can","emoji":"✈️","meta":["crime comedy","2002","Steven Spielberg"],"description":"A teenager turns into a virtuoso con man, passing himself off as a pilot, a doctor and a lawyer and forging cheques worth millions, until a dogged FBI agent takes up the chase. The film is based on the memoirs of the real fraudster Frank Abagnale.","fact":"The real Frank Abagnale, whose story is the basis of the plot, later became a consultant on bank security.","wiki_en":"Catch Me If You Can"},{"name":"Ocean's Eleven","emoji":"🎰","meta":["crime comedy","2001","Steven Soderbergh"],"description":"The professional con man Danny Ocean assembles a team of eleven specialists to rob three Las Vegas casinos in a single night. A remake of a 1960 film with an all-star cast, it became the benchmark for light, stylish heist cinema.","fact":"The shot of the crew standing in silence in front of the Bellagio fountains at the end is the film's best-known image.","wiki_en":"Ocean's Eleven (2001 film)"},{"name":"Mission: Impossible","emoji":"🕶️","meta":["action","1996","Brian De Palma"],"description":"An intelligence agent is framed after a mission in which his whole team is killed, and he has to work out alone who betrayed them while staying outside the law. Based on the cult 1960s television series, it launched Tom Cruise's long-running action franchise.","fact":"The break-in at the secure CIA vault, with the hero lowered on a cable almost to the floor, is one of the most parodied scenes in cinema.","wiki_en":"Mission: Impossible (film)"},{"name":"Casino Royale","emoji":"🎲","meta":["spy action","2006","Martin Campbell"],"description":"Newly promoted to 007, James Bond gets his first serious assignment: to beat a financier of terrorists at a poker table in a Montenegro casino. The film rebooted the Bond series with a harder, more grounded tone.","fact":"It was the first Bond film with Daniel Craig, who met scepticism from part of the fanbase at first and later won it over.","wiki_en":"Casino Royale (2006 film)"},{"name":"Rocky","emoji":"🥊","meta":["sports drama","1976","John G. Avildsen"],"description":"An unknown boxer from working-class Philadelphia gets an unlikely shot at the world champion in a title fight and takes it, to prove to himself and everyone else that he can go the distance. This low-budget film made Sylvester Stallone a star.","fact":"The hero's run up the steps of the Philadelphia Museum of Art turned them into a tourist attraction known as the Rocky Steps.","wiki_en":"Rocky"},{"name":"First Blood","emoji":"🔪","meta":["action","1982","Ted Kotcheff"],"description":"A Vietnam veteran hounded without cause by the police of a small town takes to the woods and holds off an entire posse on his own. The film opens up the hard subject of veterans returning to civilian life and introduces the character of Rambo.","fact":"Unlike the bloodbath sequels, the hero barely kills anyone in the first film — mostly he disarms and frightens his pursuers.","wiki_en":"First Blood"},{"name":"Predator","emoji":"👽","meta":["science fiction action","1987","John McTiernan"],"description":"A squad of elite commandos is sent on a rescue operation into the Central American jungle and is picked off one by one by an invisible alien hunter. The film crossed the military action movie with horror and gave the genre one of its most recognisable monsters.","fact":"The Predator suit was first built for a different actor and a different look, then completely redesigned shortly before shooting.","wiki_en":"Predator (film)"},{"name":"RoboCop","emoji":"🦾","meta":["science fiction action","1987","Paul Verhoeven"],"description":"A Detroit policeman gunned down on duty is returned to the force as a cyborg with almost no human memory left, and slowly begins to recall who he was. Paul Verhoeven's film joins brutal action to sharp satire of corporations and the media.","fact":"The violence was so extreme that the film had to be recut several times to get a releasable rating in the United States.","wiki_en":"RoboCop"},{"name":"Ghostbusters","emoji":"👻","meta":["science fiction comedy","1984","Ivan Reitman"],"description":"Three hapless parapsychologists open a private ghost-catching business in New York and promptly run into a genuine supernatural invasion. The film welded comedy to a ghost story and became a cult classic of the 1980s.","fact":"Ray Parker Jr.'s song Ghostbusters, written for the film, went to number one on the American singles chart.","wiki_en":"Ghostbusters (1984 film)"},{"name":"Men in Black","emoji":"🕶️","meta":["science fiction comedy","1997","Barry Sonnenfeld"],"description":"A secret agency in severe black suits quietly keeps watch over the aliens living among us on Earth, and a rookie takes on a dangerous case with his seasoned partner. Based on a comic, the film mixes action, jokes and inventive alien design.","fact":"The flash device that wipes witnesses' memories, the neuralyzer, became one of pop culture's instantly recognisable gadgets.","wiki_en":"Men in Black (1997 film)"},{"name":"Groundhog Day","emoji":"🔁","meta":["comedy","1993","Harold Ramis"],"description":"A cynical television weatherman gets stuck in a time loop and lives the same day in a small town over and over until he finally changes as a person. The film gave the language a phrase of its own for endless repetition.","fact":"The exact number of repeated days is never stated, but by fans' calculations it could add up to years.","wiki_en":"Groundhog Day (film)"},{"name":"The Mask","emoji":"🎭","meta":["science fiction comedy","1994","Chuck Russell"],"description":"A meek bank clerk finds an ancient mask that turns him into a manic green-faced character with superpowers and no inhibitions at all. The film made Jim Carrey the star of eccentric physical comedy and leaned hard on computer graphics for the transformations.","fact":"The comic the film is based on was far darker and nastier than the comedy that came out of it.","wiki_en":"The Mask (1994 film)"},{"name":"Dumb and Dumber","emoji":"🚐","meta":["comedy","1994","Peter Farrelly"],"description":"Two trusting halfwits drive across the country to return a forgotten briefcase of money to an attractive young woman, with no idea that it holds a kidnapper's ransom. The absurd comedy with Jim Carrey and Jeff Daniels became a 1990s classic.","fact":"The pair's van, dressed up as a shaggy dog, became one of the most recognisable vehicles in comedy cinema.","wiki_en":"Dumb and Dumber"},{"name":"The Hangover","emoji":"🐯","meta":["comedy","2009","Todd Phillips"],"description":"Three friends wake in a Las Vegas hotel suite after a wild pre-wedding night with no memory of any of it, and the groom has vanished without a trace. The comedy is built out of their attempts to reconstruct the night from scraps of evidence.","fact":"It became one of the highest-grossing R-rated comedies ever released.","wiki_en":"The Hangover"},{"name":"American Pie","emoji":"🥧","meta":["teen comedy","1999","Paul Weitz"],"description":"Four high school seniors make a pact to lose their virginity before the prom and put themselves through a string of excruciating, funny situations trying. The film became one of the defining teen comedies of the turn of the century and started a whole series.","fact":"Made on a very modest budget, the comedy unexpectedly took more than two hundred million dollars worldwide.","wiki_en":"American Pie (film)"},{"name":"The Devil Wears Prada","emoji":"👜","meta":["comedy drama","2006","David Frankel"],"description":"A journalism graduate takes a job as assistant to the tyrannical editor-in-chief of a fashion magazine and slowly loses herself chasing success in the world of high fashion. Lauren Weisberger's novel drew heavily on her own time in the industry.","fact":"The imperious editor is widely taken to be modelled on Anna Wintour, the legendary head of American Vogue.","wiki_en":"The Devil Wears Prada (film)"},{"name":"La La Land","emoji":"🎹","meta":["musical","2016","Damien Chazelle"],"description":"An aspiring actress and a jazz pianist fall in love in present-day Los Angeles while trying not to give up their own creative ambitions. The musical pays homage to the Hollywood classics of the genre and is known for its bold colour and its dance numbers.","fact":"At the Oscars the film was announced as best picture by mistake and held the award for a few minutes before the real winner was named.","wiki_en":"La La Land (film)"},{"name":"Whiplash","emoji":"🥁","meta":["drama","2014","Damien Chazelle"],"description":"An ambitious young conservatory drummer lands in the class of a cruel, exacting conductor who will humiliate his students in the name of musical perfection. The film weighs the price of obsession and runs on the duel between teacher and pupil.","fact":"J. K. Simmons won the Oscar for best supporting actor as the tyrannical mentor.","wiki_en":"Whiplash (2014 film)"},{"name":"Parasite","emoji":"🪨","meta":["social thriller","2019","Bong Joon-ho"],"description":"A poor family from a Seoul semi-basement works its way, job by job and lie by lie, into the house of a wealthy one. The South Korean film joins black comedy to a sharp social drama about inequality.","fact":"It was the first film not in English ever to win the Oscar for best picture.","wiki_en":"Parasite (2019 film)"},{"name":"Oppenheimer","emoji":"☢️","meta":["biographical drama","2023","Christopher Nolan"],"description":"The physicist Robert Oppenheimer leads the secret Manhattan Project to build the first atomic bomb, and after the war faces the political fallout and the moral weight of what he made. Christopher Nolan shot the film largely on film stock.","fact":"The atomic blast for the Trinity test scene was recreated with practical effects rather than computer graphics.","wiki_en":"Oppenheimer (film)"},{"name":"Barbie","emoji":"💗","meta":["comedy","2023","Greta Gerwig"],"description":"The classic Barbie doll, living in a perfect pink world, unexpectedly starts thinking about death and imperfection, and travels with Ken into the real world to work herself out. The film is a bright comedy and a wry look at the legacy of the most famous doll ever made.","fact":"The production bought so much pink paint for its sets that it is said to have caused a temporary shortage on the market.","wiki_en":"Barbie (film)"},{"name":"Dune","emoji":"🏜️","meta":["science fiction","2021","Denis Villeneuve"],"description":"The heir of a noble house takes charge of the desert planet Arrakis, sole source of the most valuable substance in the universe, and is drawn into lethal political intrigue. The adaptation of Frank Herbert's novel is known for its desert world and its sandworms.","fact":"For decades Frank Herbert's novel was considered unfilmable because of the complexity of its world.","wiki_en":"Dune (2021 film)"},{"name":"Top Gun: Maverick","emoji":"✈️","meta":["action","2022","Joseph Kosinski"],"description":"The veteran flyer Maverick returns to the elite pilot school as an instructor, to prepare a new generation for a mission that looks impossible. Decades after the original, the sequel became famous for filming its aerial manoeuvres for real rather than in a computer.","fact":"The actors went through flight training and were filmed inside real jets during manoeuvres, pulling genuine g-forces.","wiki_en":"Top Gun: Maverick"},{"name":"The Hunger Games","emoji":"🏹","meta":["science fiction action","2012","Gary Ross"],"description":"In a dystopian future, teenagers from the poor districts are sent every year into a televised fight to the death, and a girl volunteers in place of her younger sister. The adaptation of Suzanne Collins's novel became a defining teen franchise of its time.","fact":"The three-finger salute from the books was later taken up as a real protest symbol in several countries.","wiki_en":"The Hunger Games (film)"},{"name":"Twilight","emoji":"🧛","meta":["fantasy romance","2008","Catherine Hardwicke"],"description":"An ordinary high school girl moves to a small rainy town and falls in love with a mysterious classmate who turns out to be a vampire at war with his own nature. Stephenie Meyer's novel spawned one of the most visible teen vampire franchises.","fact":"Forks, the small town in Washington State where the story is set, became a place of pilgrimage for fans after the film came out.","wiki_en":"Twilight (2008 film)"},{"name":"The Intouchables","emoji":"🤝","meta":["comedy drama","2011","Olivier Nakache, Éric Toledano"],"description":"A rich aristocrat, paralysed after an accident, hires a young man from a poor suburb with no experience at all as his carer, and a firm friendship grows between two people who have nothing in common. The French film is based on a true story.","fact":"The plot comes from the real friendship between the businessman Philippe Pozzo di Borgo and his carer.","wiki_en":"The Intouchables"},{"name":"Amélie","emoji":"🎨","meta":["romantic comedy","2001","Jean-Pierre Jeunet"],"description":"A shy waitress in a Paris café decides to meddle secretly and ingeniously in the lives of the people around her, arranging small kindnesses while staying out of sight herself. The film is known for its vividly stylised Paris.","fact":"Many scenes were shot in a real café in Montmartre, which became a tourist attraction after the premiere.","wiki_en":"Amélie"},{"name":"Life Is Beautiful","emoji":"🎪","meta":["tragicomedy","1997","Roberto Benigni"],"description":"A Jewish father in Nazi-occupied Italy, sent to a camp with his small son, turns the nightmare around them into a game invented for the boy in order to protect his mind. The Italian film's mix of comedy and the Holocaust divided critics.","fact":"Roberto Benigni directed, co-wrote and played the lead, and won an Oscar for the performance.","wiki_en":"Life Is Beautiful"},{"name":"The Good, the Bad and the Ugly","emoji":"🤠","meta":["western","1966","Sergio Leone"],"description":"Three men after the same prize — a calculating gunslinger, a merciless hired killer and a wily cheat — follow the trail of Civil War gold buried in an unmarked grave. Sergio Leone's Italian western, scored by Ennio Morricone, closes the Dollars trilogy.","fact":"The famous three-way duel at the end is cut almost musically between close-ups of the men's faces and hands.","wiki_en":"The Good, the Bad and the Ugly"},{"name":"Psycho","emoji":"🚿","meta":["psychological thriller","1960","Alfred Hitchcock"],"description":"A young woman on the run after stealing a large sum of money stops at a lonely roadside motel run by a strange young man living under the thumb of a domineering mother. Hitchcock's film overturned every assumption about how a thriller builds tension.","fact":"The shower murder, one of the most famous scenes in cinema, took several days to shoot for a handful of seconds on screen.","wiki_en":"Psycho (1960 film)"},{"name":"The Shining","emoji":"🪓","meta":["psychological horror","1980","Stanley Kubrick"],"description":"A writer takes a job as winter caretaker of an isolated mountain hotel and moves in with his family, only to give way to the dark force living in its walls. Adapted from Stephen King, it is one of the most atmospheric and most quoted horror films ever made.","fact":"Stephen King, who wrote the novel, was unhappy with Kubrick's reading of it for years and found it too cold.","wiki_en":"The Shining (film)"},{"name":"2001: A Space Odyssey","emoji":"🪐","meta":["science fiction","1968","Stanley Kubrick"],"description":"A mysterious black monolith nudges humanity forward, from its primitive ancestors to a flight to Jupiter where a spacecraft crew falls out with a rebellious artificial intelligence. Kubrick's film is known for its almost meditative pace and its groundbreaking effects.","fact":"Many of the effects, made before anyone had walked on the Moon, still convince without a frame of computer graphics.","wiki_en":"2001: A Space Odyssey (film)"},{"name":"A Clockwork Orange","emoji":"👁️","meta":["dystopia","1971","Stanley Kubrick"],"description":"The young leader of a street gang in a dystopian London is put through an experimental state treatment designed to strip him of his taste for violence. Adapted from Anthony Burgess's novel, it caused fierce argument over its frank depiction of cruelty.","fact":"After a wave of criticism and copycat violence, Kubrick himself had the film withdrawn from British cinemas for many years.","wiki_en":"A Clockwork Orange (film)"},{"name":"Casablanca","emoji":"🍸","meta":["romance","1942","Michael Curtiz"],"description":"The owner of a bar in Casablanca, ruled by the collaborationist Vichy government, meets his former lover again when she arrives with her Resistance husband looking for a way out from the Nazis. Made during the war, it became the model Hollywood romance.","fact":"\"This is the beginning of a beautiful friendship\" and many other lines are among the most quoted in film history.","wiki_en":"Casablanca (film)"},{"name":"Gone with the Wind","emoji":"🌾","meta":["historical romance","1939","Victor Fleming"],"description":"A wilful planter's daughter lives through the American Civil War and its aftermath, fighting desperately to keep her home and chasing men she cannot have. The vast adaptation of Margaret Mitchell's novel was long the highest-grossing film ever made.","fact":"Adjusted for inflation, it is still reckoned one of the highest-grossing films in the history of cinema.","wiki_en":"Gone with the Wind (film)"},{"name":"The Wizard of Oz","emoji":"🌈","meta":["musical","1939","Victor Fleming"],"description":"A girl from Kansas is carried off by a tornado, house and all, into a magic land, and must follow the yellow brick road to the Emerald City to find a way home. One of the first colour blockbusters out of Hollywood, it became a family classic.","fact":"The switch from black-and-white Kansas to the colour of Oz is one of the most famous visual strokes in cinema.","wiki_en":"The Wizard of Oz (1939 film)"},{"name":"Breakfast at Tiffany's","emoji":"💎","meta":["romantic comedy","1961","Blake Edwards"],"description":"Holly Golightly, an eccentric New York socialite who lives on dreams of luxury and avoids attachment, strikes up a friendship with her new neighbour. Truman Capote's novella gave the century one of its style icons: black dress, long cigarette holder.","fact":"The heroine's black Givenchy dress from one of the film's best-known scenes later sold at auction for a record sum.","wiki_en":"Breakfast at Tiffany's (film)"},{"name":"Roman Holiday","emoji":"🛵","meta":["romantic comedy","1953","William Wyler"],"description":"A European princess worn out by protocol slips away from her minders for one night during a visit to Rome and, keeping her title secret, spends a day with an American journalist. It won Audrey Hepburn an Oscar for her first big Hollywood role.","fact":"The couple's scooter ride through Rome sent the popularity of the Vespa soaring after the film came out.","wiki_en":"Roman Holiday"},{"name":"One Flew Over the Cuckoo's Nest","emoji":"🏥","meta":["drama","1975","Miloš Forman"],"description":"A man who fakes mental illness to avoid prison lands in a psychiatric hospital and gradually rebels against the iron order kept by a severe head nurse. Adapted from Ken Kesey's novel, it is one of the few films to sweep all five major Oscars.","fact":"It was shot in a working psychiatric hospital in Oregon, and the hospital's own director played a small part.","wiki_en":"One Flew Over the Cuckoo's Nest (film)"},{"name":"Apocalypse Now","emoji":"🚁","meta":["war drama","1979","Francis Ford Coppola"],"description":"An American captain is sent on a secret mission to find and kill a colonel who has gone feral in the jungle and built his own cult in the middle of the Vietnam War. Inspired by Joseph Conrad, the shoot itself turned into an ordeal that ran for years.","fact":"The production ran so far over and so far out of control that a separate documentary was later made about it.","wiki_en":"Apocalypse Now"},{"name":"Seven Samurai","emoji":"⚔️","meta":["adventure drama","1954","Akira Kurosawa"],"description":"A poor Japanese village hires seven wandering samurai to defend it against the raids of bandits, and they teach the farmers to fight. Akira Kurosawa's epic shaped world cinema and was the basis of the western The Magnificent Seven.","fact":"On release it was one of the most expensive and longest productions in the history of Japanese cinema.","wiki_en":"Seven Samurai"},{"name":"The Irony of Fate","emoji":"🎄","meta":["New Year comedy","1975","Eldar Ryazanov"],"description":"On New Year's Eve a group of friends keep up their tradition of going to the bathhouse, and the tipsy hero is put on the wrong flight — waking up in another city, in a stranger's flat at an identical address. Russian television has shown it every New Year for decades.","fact":"The songs set poems by Tsvetaeva, Pasternak and Akhmadulina to music written by Mikael Tariverdiev.","wiki_en":"The Irony of Fate"},{"name":"The Diamond Arm","emoji":"💎","meta":["slapstick comedy","1968","Leonid Gaidai"],"description":"A Soviet tourist is mistaken for a smugglers' courier, and during a cruise abroad a consignment of jewels is quietly packed into the plaster cast on his arm. Leonid Gaidai's comedy was quoted and sung to pieces and is still one of the best-loved Soviet comedies.","fact":"The song from the film about the Island of Bad Luck became so popular that it took on a life of its own.","wiki_en":"The Diamond Arm"},{"name":"Operation Y and Other Shurik's Adventures","emoji":"🧱","meta":["slapstick comedy","1965","Leonid Gaidai"],"description":"Three separate stories follow the hapless student Shurik as he takes on a loafer at a building site, sits an exam, and wrecks a gang's plan to rob a warehouse. Gaidai's film features his famous trio of crooks: the Coward, the Fool and the Old Hand.","fact":"The trio of crooks first appeared in Gaidai's short films of the early 1960s and became a comic brand in their own right.","wiki_en":"Operation Y and Other Shurik's Adventures"},{"name":"Kidnapping, Caucasian Style","emoji":"🐴","meta":["slapstick comedy","1966","Leonid Gaidai"],"description":"The student Shurik, visiting the Caucasus, is unwittingly drawn into the abduction of a young woman whom a local official wants as a wife against her will, and sets out to rescue her. Gaidai's comedy with the same trio of crooks is endlessly quoted.","fact":"Lines from the film, including the toast about long-lived mountain folk and the lament \"poor little bird\", live on in everyday Russian.","wiki_en":"Kidnapping, Caucasian Style"},{"name":"Ivan Vasilievich: Back to the Future","emoji":"👑","meta":["slapstick comedy","1973","Leonid Gaidai"],"description":"An inventor's homemade time machine accidentally sends a block superintendent back to the age of Ivan the Terrible and drops the tsar himself into a Soviet flat, with farcical results. It is adapted from a play by Mikhail Bulgakov.","fact":"Both the terrible tsar and the timid superintendent Bunsha are played by the same actor, Yuri Yakovlev.","wiki_en":"Ivan Vasilievich: Back to the Future"},{"name":"Gentlemen of Fortune","emoji":"🎩","meta":["crime comedy","1971","Alexander Sery"],"description":"A good-natured kindergarten manager who looks exactly like a hardened convict is recruited to pose as a criminal and coax out of his cellmates where a stolen golden helmet is hidden. The comedy about reforming crooks was quoted at once.","fact":"Many of its lines, including \"Who would ever lock him up? He's a monument!\", went straight into everyday speech.","wiki_en":"Gentlemen of Fortune"},{"name":"Moscow Does Not Believe in Tears","emoji":"🏙️","meta":["romantic drama","1980","Vladimir Menshov"],"description":"Three young women arrive from the provinces to conquer Moscow at the end of the 1950s; the film then picks them up twenty years later, when their lives have turned out very differently. It won the Oscar for best foreign language film.","fact":"The director Vladimir Menshov could not travel to the ceremony and only received his statuette many years later.","wiki_en":"Moscow Does Not Believe in Tears"},{"name":"Office Romance","emoji":"💼","meta":["gentle comedy","1977","Eldar Ryazanov"],"description":"The stern, easily overlooked woman who runs a statistical bureau finds herself falling for a shy new employee, who sets out to help her feel more confident and more attractive. The Soviet comedy about late-blooming love is endlessly rewatched.","fact":"It grew out of the stage play Colleagues, written by Eldar Ryazanov with Emil Braginsky and already running in theatres.","wiki_en":"Office Romance"},{"name":"Love and Doves","emoji":"🕊️","meta":["gentle comedy","1984","Vladimir Menshov"],"description":"A simple family man from the back country goes off to a spa, unexpectedly falls for a flamboyant holidaymaker and leaves home for a while, as his wife and children try to get him back. Adapted from a play, it is loved for its portrait of village life.","fact":"The village drunk Uncle Mitya is played by Sergei Yursky, an actor of a wholly different, refined type, heavily made up for the role.","wiki_en":"Love and Doves"},{"name":"White Sun of the Desert","emoji":"🏜️","meta":["Soviet western","1970","Vladimir Motyl"],"description":"Demobilised Red Army soldier Sukhov, heading home across the Central Asian desert, ends up in charge of the whole harem of a fugitive bandit chief and has to protect them from their former master. Russian cosmonauts traditionally watch it before a launch.","fact":"The song Your Honour, Lady Luck, to words by Bulat Okudzhava, was sung by Pavel Luspekaev, who played the customs officer Vereshchagin.","wiki_en":"White Sun of the Desert"},{"name":"Brother","emoji":"🔫","meta":["crime drama","1997","Alexei Balabanov"],"description":"A young man just out of the army comes to Petersburg to stay with his elder brother and is slowly drawn into the criminal wars of the 1990s, acting on his own idea of justice. Alexei Balabanov's film became a defining portrait of the post-Soviet years.","fact":"The music of the band Nautilus Pompilius from the film became inseparably linked with its hero.","wiki_en":"Brother (1997 film)"},{"name":"Brother 2","emoji":"✈️","meta":["crime drama","2000","Alexei Balabanov"],"description":"The hero of the first film goes to America to find out what became of an old comrade and to set things right, in a country he neither knows nor entirely understands. The sequel handed audiences still more catchphrases and confirmed its generational status.","fact":"The exchange about where strength really lies — in money or in truth — is one of the most recognisable scenes in Russian cinema.","wiki_en":"Brother 2"},{"name":"Stalker","emoji":"🌫️","meta":["philosophical science fiction","1979","Andrei Tarkovsky"],"description":"A guide known as the Stalker leads a writer and a scientist through the mysterious, dangerous Zone to a room where, so the legend goes, your deepest wish comes true. Adapted from the Strugatsky brothers, it became a meditative parable about faith and desire.","fact":"A great deal of the footage had to be reshot after the film stock was ruined in processing, and production dragged on for years.","wiki_en":"Stalker (1979 film)"},{"name":"Citizen Kane","emoji":"📰","meta":["drama","1941","Orson Welles"],"description":"Orson Welles's first feature, on the rise and fall of the newspaper magnate Charles Foster Kane, told through the memories of the people who knew him. It transformed cinematography, editing and storytelling and topped best-ever lists for decades.","fact":"The mysterious dying word \"Rosebud\" became one of cinema's most discussed symbols, and baffles the film's own characters almost to the end.","wiki_en":"Citizen Kane"},{"name":"On the Waterfront","emoji":"⚓","meta":["drama","1954","Elia Kazan"],"description":"Elia Kazan's film about the former boxer Terry Malloy, a longshoreman caught between the union mob and his own conscience. Marlon Brando gave one of the defining performances of his career, and the picture won eight Oscars, including best picture.","fact":"Terry's conversation with his brother in the back of a taxi is one of the most quoted and most dissected acting scenes ever filmed.","wiki_en":"On the Waterfront"},{"name":"Lawrence of Arabia","emoji":"🐪","meta":["epic","1962","David Lean"],"description":"David Lean's epic about the British officer T. E. Lawrence, who united the Arab tribes in revolt against the Ottoman Empire during the First World War. The film became famous for its desert photography and won seven Oscars, including best picture.","fact":"The part made the near-unknown stage actor Peter O'Toole a star and brought him the first of eight Oscar nominations, none of which he ever won.","wiki_en":"Lawrence of Arabia (film)"},{"name":"Ben-Hur","emoji":"🏇","meta":["historical drama","1959","William Wyler"],"description":"From Lew Wallace's novel: a Judean nobleman, Judah Ben-Hur, betrayed by a childhood friend and sold into slavery, returns to seek justice in the time of Christ. The film is famous for its colossal chariot race and set a record of eleven Oscars.","fact":"The chariot race took several weeks to shoot on an enormous arena built for the film at the Cinecittà studio in Rome.","wiki_en":"Ben-Hur (1959 film)"},{"name":"West Side Story","emoji":"💃","meta":["musical","1961","Robert Wise"],"description":"A musical drama about the feud between two New York street gangs, the Jets and the Sharks, against which the forbidden love of Tony and Maria plays out in the spirit of Romeo and Juliet. Leonard Bernstein's Broadway score won it ten Oscars.","fact":"The choreography was by Jerome Robbins, who shared the director's credit with Robert Wise.","wiki_en":"West Side Story (1961 film)"},{"name":"The Sound of Music","emoji":"🎶","meta":["musical","1965","Robert Wise"],"description":"The novice Maria becomes governess to the seven children of a stern Austrian captain, von Trapp, brings the family together through song, and then helps them flee the Nazis who have annexed Austria. The Rodgers and Hammerstein musical was a huge hit.","fact":"The Alpine meadows of the opening were filmed around Salzburg, which has been a tourist attraction ever since.","wiki_en":"The Sound of Music (film)"},{"name":"Rebecca","emoji":"🏚️","meta":["thriller","1940","Alfred Hitchcock"],"description":"Alfred Hitchcock's first Hollywood film, from Daphne du Maurier's novel: the young wife of a rich widower moves into his estate, Manderley, and feels the unseen presence of his dead first wife everywhere. The mystery and the pressure won it best picture.","fact":"The name of the heroine who narrates the story is never once spoken in the entire film.","wiki_en":"Rebecca (1940 film)"},{"name":"Vertigo","emoji":"🌀","meta":["thriller","1958","Alfred Hitchcock"],"description":"A detective with a fear of heights falls for the mysterious woman he has been hired to follow, and the obsession pulls him into a web of deceit. Hitchcock used a new trick, tracking in while zooming out, that came to be called the vertigo effect.","fact":"Coolly received on release, it topped the Sight & Sound critics' poll of the greatest films ever made half a century later.","wiki_en":"Vertigo (film)"},{"name":"Rear Window","emoji":"🔭","meta":["thriller","1954","Alfred Hitchcock"],"description":"A photographer confined to a wheelchair watches his neighbours out of the window from sheer boredom and starts to suspect one of them of murdering his wife. Almost the whole film takes place within a single room, making it Hitchcock's most confined thriller.","fact":"The courtyard and the surrounding flats were all built in a studio as one huge set.","wiki_en":"Rear Window"},{"name":"The Birds","emoji":"🐦","meta":["horror","1963","Alfred Hitchcock"],"description":"In a coastal Californian town the birds begin attacking people en masse for no reason anyone can see, turning ordinary life into a nightmare. Hitchcock deliberately went without a score, using the shrieking of birds and the beating of wings instead.","fact":"The attack scenes used both mechanical and live birds, some of them literally tied to the actors' clothes with fishing line.","wiki_en":"The Birds (film)"},{"name":"Some Like It Hot","emoji":"🎷","meta":["comedy","1959","Billy Wilder"],"description":"Two musicians accidentally witness a gangland killing and, hiding from the mob, dress as women and join an all-female jazz band. The comedy with Marilyn Monroe is regularly called the finest ever made in American cinema.","fact":"Marilyn Monroe needed dozens of takes to deliver one simple line, and the story became a piece of film legend.","wiki_en":"Some Like It Hot"},{"name":"The Bridge on the River Kwai","emoji":"🌉","meta":["war drama","1957","David Lean"],"description":"British prisoners of war in a Japanese camp are forced to build a railway bridge, and their commander turns the work into a point of honour, forgetting that the bridge will serve the enemy. It won seven Oscars, including best picture and best director.","fact":"The Colonel Bogey March whistled by the prisoners became one of the most recognisable tunes in film music.","wiki_en":"The Bridge on the River Kwai"},{"name":"Out of Africa","emoji":"🦁","meta":["drama","1985","Sydney Pollack"],"description":"Based on the memoirs of the Danish writer Karen Blixen: her life on a coffee plantation in Kenya in the early twentieth century and her affair with the hunter and adventurer Denys Finch Hatton. With Meryl Streep and Robert Redford, it won seven Oscars.","fact":"Karen Blixen's actual house in Kenya is now a museum devoted to the writer and to this film.","wiki_en":"Out of Africa (film)"},{"name":"Dances with Wolves","emoji":"🐺","meta":["western","1990","Kevin Costner"],"description":"A Union officer during the American Civil War is posted to a remote frontier station and gradually draws close to a Sioux band, taking on their way of life and their values. Kevin Costner's directing debut, in which he also starred, won seven Oscars.","fact":"A great deal of the dialogue is in Lakota with English subtitles — a rare thing for a Hollywood blockbuster.","wiki_en":"Dances with Wolves"},{"name":"The English Patient","emoji":"🏜️","meta":["drama","1996","Anthony Minghella"],"description":"In a war-ruined Italian monastery a nurse looks after a patient burned beyond recognition whose identity is a mystery, and out of his memories a tragic love story set in the North African desert takes shape. Michael Ondaatje's novel won nine Oscars on screen.","fact":"The desert scenes were shot in the Sahara in southern Tunisia, and the monastery scenes in a genuine old cloister in Tuscany.","wiki_en":"The English Patient (film)"},{"name":"Amadeus","emoji":"🎼","meta":["drama","1984","Miloš Forman"],"description":"The story of the composer Antonio Salieri and the brilliant, unruly Wolfgang Amadeus Mozart, told by an aged Salieri eaten up by envy and remorse. Miloš Forman's film won eight Oscars, including best picture.","fact":"For all the drama of the rivalry, historians treat the feud between Salieri and Mozart as invention.","wiki_en":"Amadeus (film)"},{"name":"Once Upon a Time in America","emoji":"🎩","meta":["crime drama","1984","Sergio Leone"],"description":"An ageing gangster nicknamed Noodles returns to New York decades later and remembers his youth on the streets of the Jewish quarter, the friendship and the betrayal that bound him to his childhood gang. Sergio Leone's last film is his epic testament.","fact":"The original cut runs almost four hours; for American cinemas it was heavily trimmed and re-edited into chronological order.","wiki_en":"Once Upon a Time in America"},{"name":"The Exorcist","emoji":"😈","meta":["horror","1973","William Friedkin"],"description":"After inexplicable changes in her twelve-year-old daughter's behaviour, an actress turns to priests, who perform the rite of driving a demon out of the girl. William Friedkin's film was among the first horror pictures nominated for best picture.","fact":"At the first screenings some members of the audience fainted, so strong was the film's effect on them.","wiki_en":"The Exorcist"},{"name":"King Kong","emoji":"🦍","meta":["adventure","1933","Merian C. Cooper and Ernest B. Schoedsack"],"description":"A film crew sails to a lost island, finds a giant ape, King Kong, worshipped by the islanders as a god, and brings him to New York to be gawped at. The 1933 film was a breakthrough in composite photography and stop-motion and founded a whole franchise.","fact":"The King Kong model used for the stop-motion was only about half a metre tall, though it looks colossal on screen.","wiki_en":"King Kong (1933 film)"},{"name":"Lincoln","emoji":"🎩","meta":["biographical drama","2012","Steven Spielberg"],"description":"Steven Spielberg's film concentrates on the last months of President Abraham Lincoln's life, as he fights the political battle to pass the Thirteenth Amendment and abolish slavery. Daniel Day-Lewis won the third Oscar of his career as Lincoln.","fact":"Daniel Day-Lewis prepared by reconstructing Lincoln's manner of speech and his walk from contemporaries' descriptions.","wiki_en":"Lincoln (film)"},{"name":"Love Actually","emoji":"❤️","meta":["romantic comedy","2003","Richard Curtis"],"description":"A Christmas comedy that weaves together the stories of a dozen Londoners, from the prime minister to a schoolboy, each of them finding or losing love in the run-up to the holiday. The star-studded ensemble became one of the best-loved Christmas films.","fact":"Made on a modest budget, it took several times its cost worldwide and comes back to screens every Christmas.","wiki_en":"Love Actually"},{"name":"The Notebook","emoji":"💌","meta":["romance","2004","Nick Cassavetes"],"description":"An elderly man reads to a resident of a nursing home the love story of two young people from different classes, separated by war and circumstance but holding on to their feelings for years. Nicholas Sparks's novel became one of the great romances of the 2000s.","fact":"The film was shot in South Carolina, although the book it comes from is set in neighbouring North Carolina.","wiki_en":"The Notebook (2004 film)"},{"name":"The Godfather Part II","emoji":"🍷","meta":["crime drama","1974","Francis Ford Coppola"],"description":"The Corleone saga continues along two parallel lines: the young Vito Corleone making his name at the turn of the century, and his son Michael tightening his grip on power in post-war America. It was the first sequel ever to win best picture.","fact":"Robert De Niro won an Oscar as the young Vito Corleone, although most of his lines are spoken in Sicilian.","wiki_en":"The Godfather Part II"},{"name":"The Prestige","emoji":"🎩","meta":["mystery drama","2006","Christopher Nolan"],"description":"Two London magicians at the end of the nineteenth century turn professional rivalry into a private war of attrition, outbidding each other with ever more dangerous illusions. Nolan built the film as a puzzle across several timelines that only resolves at the end.","fact":"The title refers to the third and final act of a magic trick, which the characters themselves discuss outright.","wiki_en":"The Prestige (film)"},{"name":"Dunkirk","emoji":"🪖","meta":["war drama","2017","Christopher Nolan"],"description":"The film recreates the evacuation of British and Allied troops from the French coast in 1940, when the army was pinned against the sea by German forces. Nolan tells it along three lines — land, sea and air — each running on a different timescale.","fact":"Real Second World War aircraft were used for the aerial sequences rather than computer graphics alone.","wiki_en":"Dunkirk (2017 film)"},{"name":"Tenet","emoji":"⏳","meta":["science fiction","2020","Christopher Nolan"],"description":"A nameless agent is charged with heading off a threat that could end the world, and to do it he learns a technology that reverses the flow of time and lets him move into the past as though through a mirror. One of Nolan's most intricate films.","fact":"Many of the \"reversed\" stunt scenes were filmed by having the performers actually move backwards, rather than by running the film in reverse.","wiki_en":"Tenet (film)"},{"name":"The Dark Knight Rises","emoji":"🦇","meta":["superhero film","2012","Christopher Nolan"],"description":"Eight years after the previous film, an ageing and disillusioned Bruce Wayne has to put the cape back on when Gotham is threatened by the merciless mercenary Bane. The last part of Nolan's Batman trilogy was among the biggest superhero hits of its time.","fact":"Tom Hardy built a peculiar low voice for Bane that had to be partly re-dubbed after audiences complained they could not make it out.","wiki_en":"The Dark Knight Rises"},{"name":"Man of Steel","emoji":"🦸","meta":["superhero film","2013","Zack Snyder"],"description":"The film rethinks Superman's origin: an alien from the planet Krypton raised on Earth as Clark Kent learns to accept his own nature and decides how to use his powers for humanity. Zack Snyder's picture rebooted the DC film universe.","fact":"For the first time in decades, the Superman suit here drops the familiar red trunks worn over the tights.","wiki_en":"Man of Steel (film)"},{"name":"Batman v Superman: Dawn of Justice","emoji":"⚔️","meta":["superhero film","2016","Zack Snyder"],"description":"Alarmed by Superman's destructive power, Batman decides he has to stop him before he becomes a threat to humanity, and their quarrel turns into an epic fight between DC's two best-known heroes. The film also introduced the first screen Wonder Woman.","fact":"This is Wonder Woman's first big-screen appearance, played by Gal Gadot, who went on to headline a series of her own.","wiki_en":"Batman v Superman: Dawn of Justice"},{"name":"Justice League","emoji":"🦸‍♂️","meta":["superhero film","2017","Zack Snyder"],"description":"Batman and Wonder Woman put together a team of superheroes — the Flash, Aquaman and Cyborg — to face the alien invader Steppenwolf, who has come for the sources of power hidden on Earth. It brought DC's key heroes together on screen for the first time.","fact":"After Zack Snyder left, Joss Whedon finished part of the shoot and the edit, and years later Snyder's own version was released separately.","wiki_en":"Justice League (film)"},{"name":"Aquaman","emoji":"🔱","meta":["superhero film","2018","James Wan"],"description":"Half human, half Atlantean, Arthur Curry learns that he is the rightful heir to the underwater throne of Atlantis and has to head off the war between ocean and land that his half-brother is preparing. James Wan's film was among DC's biggest hits.","fact":"Many underwater scenes were shot in dry tanks, with a wire rig simulating weightlessness instead of real water.","wiki_en":"Aquaman (film)"},{"name":"Wonder Woman","emoji":"🛡️","meta":["superhero film","2017","Patty Jenkins"],"description":"Diana, an Amazon raised on an island of warrior women, leaves home to help stop the First World War and meets the world of men for the first time outside the sheltered paradise of Themyscira. It was the first big-budget superhero film directed by a woman.","fact":"Gal Gadot served in the Israeli army before she became an actress, which helped her prepare for the fight scenes.","wiki_en":"Wonder Woman (2017 film)"},{"name":"Suicide Squad","emoji":"💣","meta":["superhero film","2016","David Ayer"],"description":"A government agency assembles a team of dangerous supervillains out of prison, offering them shorter sentences in exchange for lethal secret operations. David Ayer's film introduced audiences to DC's cult villains, among them the Joker and Harley Quinn.","fact":"Margot Robbie prepared for Harley Quinn by working through the character's old comics and the animated series of the 1990s.","wiki_en":"Suicide Squad (2016 film)"},{"name":"Logan","emoji":"🐾","meta":["superhero film","2017","James Mangold"],"description":"Ageing and no longer able to heal, Logan is hiding out near the border with the ailing Professor Xavier when he meets a girl with powers much like his own. James Mangold's bleak, brutal film was rated R and nominated for best adapted screenplay.","fact":"Alongside the normal version, a wholly black-and-white cut was also released, under the title Logan Noir.","wiki_en":"Logan (film)"},{"name":"X-Men","emoji":"🧬","meta":["superhero film","2000","Bryan Singer"],"description":"In the near future, mutants with unusual powers hide from a hostile society, while Professor Xavier gathers a team of young mutants to defend the peaceful coexistence of mutants and humans. The film launched one of the longest-running superhero series.","fact":"The costumes were deliberately made in black leather instead of the bright comic-book tights, to keep the film looking real.","wiki_en":"X-Men (film)"},{"name":"X2: X-Men United","emoji":"🧬","meta":["superhero film","2003","Bryan Singer"],"description":"A mutant attack on the American president gives a military colonel his excuse to launch a full campaign against all mutants, forcing the X-Men to join their own enemies to survive. The sequel greatly widened the world of the first film.","fact":"Many critics and fans call it one of the rare sequels that surpassed the original.","wiki_en":"X2 (film)"},{"name":"The Wolverine","emoji":"🗡️","meta":["superhero film","2013","James Mangold"],"description":"Logan travels to Japan at the invitation of a dying magnate whose life he once saved, and is drawn into a fight over the inheritance that may cost him his immortality for the first time. James Mangold shifted the focus from vast battles to personal drama.","fact":"The plot draws in part on the cult Wolverine comics by Chris Claremont and Frank Miller.","wiki_en":"The Wolverine (film)"},{"name":"Captain America: The First Avenger","emoji":"🛡️","meta":["superhero film","2011","Joe Johnston"],"description":"Steve Rogers, a frail but fearless young man in the Second World War, becomes the subject of a secret experiment that turns him into a super-soldier, and takes on the Nazi organisation Hydra. The film set up Captain America's place in the Marvel universe.","fact":"The scrawny Steve Rogers was achieved by digitally shrinking Chris Evans and by shooting a slighter double with the actor's face composited on.","wiki_en":"Captain America: The First Avenger"},{"name":"Thor","emoji":"🔨","meta":["superhero film","2011","Kenneth Branagh"],"description":"Thor, the arrogant heir to the throne of Asgard, is banished to Earth by his father for breaking the peace, stripped of his divine powers and of the hammer Mjolnir, and has to prove himself worthy of the title. The film brought Norse myth into the Marvel films.","fact":"Chris Hemsworth put on a visible amount of muscle for the part, transforming his physique over a few months of preparation.","wiki_en":"Thor (film)"},{"name":"Doctor Strange","emoji":"🌀","meta":["superhero film","2016","Scott Derrickson"],"description":"Stephen Strange, a brilliant and self-satisfied neurosurgeon whose hands lose their precision in a crash, goes looking for a cure, finds a secret school in Kathmandu and discovers magic and parallel dimensions. The film is known for its folding cityscapes.","fact":"The bending city scenes were inspired by the optical illusions of the artist M. C. Escher.","wiki_en":"Doctor Strange (2016 film)"},{"name":"Black Panther","emoji":"🐾","meta":["superhero film","2018","Ryan Coogler"],"description":"After his father's death, Prince T'Challa returns to Wakanda, a technologically advanced African kingdom hidden from the world, to take the throne and defend it from enemies within and without. It was the first superhero film nominated for best picture.","fact":"The costume and production designers drew on the real traditions of several African cultures to invent the look of Wakanda.","wiki_en":"Black Panther (film)"},{"name":"Ant-Man","emoji":"🐜","meta":["superhero film","2015","Peyton Reed"],"description":"The small-time thief Scott Lang is given a suit by the inventor Hank Pym that lets him shrink to the size of an insect and command an army of ants, and he has to use it to stop a dangerous technology being stolen. The film brought Marvel an unusually intimate, comic tone.","fact":"The idea of the Ant-Man suit appeared in the comics as early as 1962, long before superhero film universes existed.","wiki_en":"Ant-Man (film)"},{"name":"Spider-Man: Into the Spider-Verse","emoji":"🕸️","meta":["animation","2018","Bob Persichetti, Peter Ramsey, Rodney Rothman"],"description":"The teenager Miles Morales gains the same powers as Peter Parker and meets several versions of Spider-Man from parallel universes, all of them facing one shared threat. The film won the animation Oscar and its comic-book style changed what superhero animation could look like.","fact":"The artists developed a technique that imitates the frame rate of old comics and even the dots of the printing screen.","wiki_en":"Spider-Man: Into the Spider-Verse"},{"name":"Venom","emoji":"👅","meta":["superhero film","2018","Ruben Fleischer"],"description":"The investigative journalist Eddie Brock, digging into a corporation, is infected by an alien symbiote that fuses with his body and grants inhuman strength, demanding in return that he give in to its predatory instincts. The film runs on the tension between the two inside one body.","fact":"Venom first appeared in the Spider-Man comics in the late 1980s as his dark opposite.","wiki_en":"Venom (2018 film)"},{"name":"The Chronicles of Narnia: The Lion, the Witch and the Wardrobe","emoji":"🦁","meta":["fantasy","2005","Andrew Adamson"],"description":"Four children evacuated from wartime London stumble through a wardrobe into Narnia, a magic land held in endless winter by the wicked White Witch, and take the side of the lion Aslan. The adaptation of C. S. Lewis opened a whole series of Narnia films.","fact":"The snowbound Narnian landscapes were shot in New Zealand, the same country as The Lord of the Rings trilogy.","wiki_en":"The Chronicles of Narnia: The Lion, the Witch and the Wardrobe"},{"name":"The Lord of the Rings: The Two Towers","emoji":"💍","meta":["fantasy","2002","Peter Jackson"],"description":"The second part of Peter Jackson's trilogy follows the broken Fellowship: Frodo and Sam make for Mordor with Gollum as their guide, while the others are drawn into the huge battle for the fortress of Helm's Deep. That battle is one of the most impressive ever filmed.","fact":"Gollum was created with motion capture, a technique the actor Andy Serkis did much to perfect.","wiki_en":"The Lord of the Rings: The Two Towers"},{"name":"The Lord of the Rings: The Return of the King","emoji":"👑","meta":["fantasy","2003","Peter Jackson"],"description":"The last part of Peter Jackson's trilogy brings every thread together: the armies of good prepare for the decisive battle at the walls of Minas Tirith while Frodo and Sam press on alone towards Mount Doom. It won a record eleven Oscars, including best picture.","fact":"It is one of the very few fantasy films ever to win the Oscar for best picture.","wiki_en":"The Lord of the Rings: The Return of the King"},{"name":"The Hobbit: An Unexpected Journey","emoji":"🗝️","meta":["fantasy","2012","Peter Jackson"],"description":"The quiet hobbit Bilbo Baggins finds himself joining a company of dwarves setting out to win back their ancient home, the Lonely Mountain, from the dragon Smaug. The first part of the prequel trilogy returned audiences to Middle-earth a decade after the original saga.","fact":"It was shot at a higher frame rate, 48 per second instead of the usual 24, and shown that way in some cinemas, which divided audiences.","wiki_en":"The Hobbit: An Unexpected Journey"},{"name":"Harry Potter and the Chamber of Secrets","emoji":"🐍","meta":["fantasy","2002","Chris Columbus"],"description":"In their second year at Hogwarts, Harry and his friends face mysterious attacks on pupils and try to solve the riddle of the legendary Chamber of Secrets, said to be hidden in the school's walls. The second film deepened the mythology and the darkness of the magical world.","fact":"This is the first film in which we hear Parseltongue, the snake language Harry turns out to speak.","wiki_en":"Harry Potter and the Chamber of Secrets (film)"},{"name":"Harry Potter and the Prisoner of Azkaban","emoji":"🐺","meta":["fantasy","2004","Alfonso Cuarón"],"description":"Word reaches Hogwarts that the dangerous criminal Sirius Black has escaped, and the school is patrolled by the sinister guards of Azkaban, dementors who feed on human feeling. A change of director gave the third film a darker, visually richer style.","fact":"Alfonso Cuarón asked the actors to write essays in the voice of their characters, to understand them better before filming.","wiki_en":"Harry Potter and the Prisoner of Azkaban (film)"},{"name":"Harry Potter and the Goblet of Fire","emoji":"🔥","meta":["fantasy","2005","Mike Newell"],"description":"Hogwarts hosts the Triwizard Tournament, with pupils arriving from other magical schools of Europe, and Harry Potter's name turns up among the champions although he never entered. The fourth film took the story out of the school and into an international contest.","fact":"Mike Newell was the first British director in the series: the earlier Potter films were made by an American and a Mexican.","wiki_en":"Harry Potter and the Goblet of Fire (film)"},{"name":"Harry Potter and the Deathly Hallows – Part 2","emoji":"⚡","meta":["fantasy","2011","David Yates"],"description":"The final film of the Harry Potter saga brings the last battle between the forces of good and Voldemort inside the walls of Hogwarts itself, turned into a vast battlefield. It closed one of the longest-running and highest-grossing franchises in cinema.","fact":"It is the highest-grossing film of the series and the only one of the eight to take more than a billion dollars worldwide.","wiki_en":"Harry Potter and the Deathly Hallows – Part 2"},{"name":"Fantastic Beasts and Where to Find Them","emoji":"🐾","meta":["fantasy","2016","David Yates"],"description":"This spin-off from the world of Harry Potter moves to 1920s New York, where the eccentric magizoologist Newt Scamander travels with a suitcase full of magical creatures and accidentally lets some of them loose. It takes its name from a book Newt writes in that universe.","fact":"For the first time in the series the screenplay was written by J. K. Rowling herself, rather than adapted from her books.","wiki_en":"Fantastic Beasts and Where to Find Them (film)"},{"name":"Star Wars: Episode V – The Empire Strikes Back","emoji":"❄️","meta":["space opera","1980","Irvin Kershner"],"description":"The rebels retreat to the ice planet Hoth under the Empire's assault, and Luke Skywalker goes to the swamp world of Dagobah to train with the wise Jedi master Yoda while his friends try to shake off imperial pursuit. Many call it the best film of the saga.","fact":"This is where audiences first meet Yoda, conceived as a puppet worked by puppeteers.","wiki_en":"The Empire Strikes Back"},{"name":"Star Wars: Episode VI – Return of the Jedi","emoji":"🌲","meta":["space opera","1983","Richard Marquand"],"description":"Luke Skywalker returns to free Han Solo from the carbonite, while the rebels prepare a decisive strike on the Empire's new Death Star with unexpected help from the forest dwellers of Endor. The film closed the original Star Wars trilogy.","fact":"The furry forest dwellers of Endor, the Ewoks, were invented for this film and remain among the saga's most recognisable creatures.","wiki_en":"Return of the Jedi"},{"name":"Star Wars: Episode I – The Phantom Menace","emoji":"🤖","meta":["space opera","1999","George Lucas"],"description":"Two Jedi knights are sent to protect the queen of Naboo from a trade blockade and find, on the desert world of Tatooine, a slave boy called Anakin Skywalker with an unusually strong connection to the Force. The first prequel showed how Darth Vader's story began.","fact":"Jar Jar Binks was one of the first fully computer-generated characters to carry a large role alongside live actors.","wiki_en":"Star Wars: Episode I – The Phantom Menace"},{"name":"Star Wars: The Force Awakens","emoji":"⚡","meta":["space opera","2015","J. J. Abrams"],"description":"Decades after the fall of the Empire a new threat, the First Order, hangs over the galaxy, and the scavenger Rey and the former stormtrooper Finn are pulled into a struggle that continues the original trilogy. The film opened a new era and brought the old heroes back.","fact":"The makers deliberately relied on practical sets and real robots rather than going over entirely to computer graphics.","wiki_en":"Star Wars: The Force Awakens"},{"name":"Rogue One: A Star Wars Story","emoji":"🛰️","meta":["space opera","2016","Gareth Edwards"],"description":"A team of rebel scouts led by Jyn Erso is sent on a desperate mission to steal the plans of the Death Star, shortly before the events of the 1977 film. The first standalone Star Wars spin-off is about the price nameless people pay for a shared victory.","fact":"Several characters from the classic trilogy were recreated with computer graphics so that they could appear young again.","wiki_en":"Rogue One"},{"name":"Star Trek","emoji":"🖖","meta":["science fiction","2009","J. J. Abrams"],"description":"This reboot of the legendary franchise follows the young James Kirk and Mr Spock, who meet aboard the starship Enterprise and learn to work together against a vengeful alien from the future. It introduced a new generation to the world of Star Trek.","fact":"The plot uses an alternative timeline, which let the makers rethink the classic characters without breaking the canon of the old series.","wiki_en":"Star Trek (2009 film)","wiki_ru":"Звёздный путь (фильм, 2009)"},{"name":"Aliens","emoji":"👽","meta":["science fiction","1986","James Cameron"],"description":"Decades after her encounter with the alien predator, warrant officer Ellen Ripley goes with a squad of space marines to a colonised planet where contact with the settlers has been lost, and finds a whole swarm of the creatures. The sequel swapped horror for a war film.","fact":"Sigourney Weaver was nominated for a best actress Oscar as Ripley, a rare thing indeed for science fiction action.","wiki_en":"Aliens (film)"},{"name":"The Terminator","emoji":"🤖","meta":["science fiction","1984","James Cameron"],"description":"A killer cyborg is sent back from the future to Los Angeles, programmed to destroy a woman named Sarah Connor, and a soldier follows to protect her. James Cameron's low-budget film became a science fiction classic and made Arnold Schwarzenegger a world star.","fact":"The terminator's \"I'll be back\" was an ordinary functional line in the script and became one of the most famous quotes in cinema.","wiki_en":"The Terminator"},{"name":"Terminator 3: Rise of the Machines","emoji":"🤖","meta":["science fiction","2003","Jonathan Mostow"],"description":"Years after judgment day was averted, a grown-up John Connor is again the target of a newer, more advanced killer terminator, and another protector model arrives to defend him. The third film continued the story without the series' founding director.","fact":"The villain here is the T-X, the first female terminator model in the franchise.","wiki_en":"Terminator 3: Rise of the Machines"},{"name":"The Matrix Reloaded","emoji":"💊","meta":["science fiction","2003","The Wachowskis"],"description":"Neo and his allies from Zion carry on the fight against the machines holding humanity in a virtual reality, and run into new revelations about the nature of the Matrix and their own place in it. The second film widened the original's philosophy and its action.","fact":"Neo's fight against dozens of copies of Agent Smith required a technology for cloning the actor digitally across hundreds of takes.","wiki_en":"The Matrix Reloaded"},{"name":"The Matrix Revolutions","emoji":"🕶️","meta":["science fiction","2003","The Wachowskis"],"description":"The last part of the trilogy brings the war between people and machines to its decisive point, with the fate of Zion and of the Matrix itself resting on Neo's final moves in both worlds, real and virtual. It reached cinemas only months after the previous film.","fact":"Its release was staged as a global event: the film opened worldwide at practically the same hour across every time zone.","wiki_en":"The Matrix Revolutions"},{"name":"Back to the Future Part II","emoji":"🛹","meta":["science fiction","1989","Robert Zemeckis"],"description":"Marty McFly and Doc Emmett Brown fly the time-travelling car to 2015 to head off a disaster in his family's future, but one accidental interference bends both the past and the present out of shape. The sequel is famous for predictions that partly came true.","fact":"The hoverboard shown in the film has been chased ever since by engineers and enthusiasts trying to build a real one.","wiki_en":"Back to the Future Part II"},{"name":"Back to the Future Part III","emoji":"🤠","meta":["science fiction","1990","Robert Zemeckis"],"description":"Marty McFly takes the time machine back to 1885 and the Wild West to rescue Doc Brown, who is stranded there and has fallen in love with the local schoolteacher. The final part swapped the futuristic setting for the western, keeping the series' humour intact.","fact":"The second and third films were made as one production block, and opened about six months apart.","wiki_en":"Back to the Future Part III"},{"name":"Indiana Jones and the Temple of Doom","emoji":"💎","meta":["adventure","1984","Steven Spielberg"],"description":"The adventuring archaeologist Indiana Jones ends up in an Indian village where a local cult is stealing children and a sacred stone, and has to go down into an underground temple full of lethal traps. This prequel to Raiders is darker and harsher than the rest.","fact":"It was partly because of this film's brutal scenes that the American ratings system later added the intermediate PG-13 category.","wiki_en":"Indiana Jones and the Temple of Doom"},{"name":"Indiana Jones and the Last Crusade","emoji":"🏺","meta":["adventure","1989","Steven Spielberg"],"description":"Indiana Jones sets out to find his missing father and the legendary Holy Grail, racing Nazi agents who are after the relic too. This is the first time his father, Professor Henry Jones, played by Sean Connery, comes along on an adventure.","fact":"Sean Connery, playing Indiana's father, was in fact only twelve years older than Harrison Ford.","wiki_en":"Indiana Jones and the Last Crusade"},{"name":"Pirates of the Caribbean: Dead Man's Chest","emoji":"🐙","meta":["adventure","2006","Gore Verbinski"],"description":"Captain Jack Sparrow tries to settle his debt to Davy Jones, captain of the Flying Dutchman, while Will Turner and Elizabeth Swann are caught up in a dangerous chase after the chest that holds the sea lord's heart. The second film widened the cursed-seas mythology.","fact":"To give Davy Jones his tentacled face, Bill Nighy had to perform in a motion capture suit.","wiki_en":"Pirates of the Caribbean: Dead Man's Chest"},{"name":"Pirates of the Caribbean: At World's End","emoji":"🏴‍☠️","meta":["adventure","2007","Gore Verbinski"],"description":"Pirate captains from every sea gather in the Brethren Court to face the East India Trading Company, which means to wipe out piracy for good, while Jack Sparrow's friends have to fetch him back from the land of the dead. The third film closed the Black Pearl story.","fact":"For the huge final battle at the maelstrom, giant sets were built on a gyroscope platform that could rotate.","wiki_en":"Pirates of the Caribbean: At World's End"},{"name":"The Fast and the Furious","emoji":"🏎️","meta":["action","2001","Rob Cohen"],"description":"An undercover policeman infiltrates the street racing scene of Los Angeles to investigate a string of truck robberies, and finds himself drawn to the crew's leader and his sister. The first film about illegal racing began one of the longest-running series in cinema.","fact":"The first film's budget was fairly modest, but the cult of street racing and tuning it created carried the series into blockbuster territory.","wiki_en":"The Fast and the Furious (2001 film)","wiki_ru":"Форсаж (фильм, 2001, США)"},{"name":"Furious 7","emoji":"🚗","meta":["action","2015","James Wan"],"description":"The crew of street racers and former criminals takes on a hired killer avenging his brother, and the action moves from American highways to the streets of Abu Dhabi and the mountain roads of the Caucasus. It is one of the highest-grossing films in the franchise.","fact":"Filming stopped when Paul Walker died in a car crash: the script was rewritten and his remaining scenes finished with his brothers and computer graphics.","wiki_en":"Furious 7"},{"name":"Mission: Impossible II","emoji":"🕶️","meta":["action","2000","John Woo"],"description":"Agent Ethan Hunt goes to Sydney to stop a former colleague who has stolen a lethal virus and plans to sell it together with the vaccine, profiting from an engineered epidemic. The second film stands out for John Woo's vivid, almost balletic action choreography.","fact":"Tom Cruise did many of the stunts himself, including the rock climbing at the start of the film, without a double.","wiki_en":"Mission: Impossible II"},{"name":"Mission: Impossible – Ghost Protocol","emoji":"🏙️","meta":["action","2011","Brad Bird"],"description":"After an explosion in the Kremlin for which IMF agents are blamed, the organisation is disbanded, and Ethan Hunt and a small team have to work alone, without government backing, to head off a nuclear threat. The film is famous for the climb up the world's tallest tower.","fact":"Tom Cruise shot the Burj Khalifa sequence at a real height of more than four hundred metres, with minimal digital work.","wiki_en":"Mission: Impossible – Ghost Protocol"},{"name":"Goldfinger","emoji":"🔫","meta":["action","1964","Guy Hamilton"],"description":"Agent 007 James Bond investigates the gold magnate Goldfinger, who is hatching an audacious plan to irradiate the gold reserve at Fort Knox and wreck the world economy. The third Bond film fixed the formula: the gadget car, the flamboyant villain, the femme fatale.","fact":"This is where Bond's famous Aston Martin DB5 first appeared, becoming one of the symbols of the franchise.","wiki_en":"Goldfinger (film)"},{"name":"No Time to Die","emoji":"🎯","meta":["action","2021","Cary Joji Fukunaga"],"description":"Retired from the service, James Bond is enjoying a quiet life in Jamaica until an old friend from the CIA asks for help finding a kidnapped scientist whose project hides a lethal weapon. The fifth and last film with Daniel Craig closed the character's long arc.","fact":"At around 163 minutes it is the longest film in the official Bond series.","wiki_en":"No Time to Die"},{"name":"Skyfall","emoji":"🏴","meta":["action","2012","Sam Mendes"],"description":"After a botched operation and a bullet wound, James Bond returns to duty to hunt down a former MI6 agent turned cyberterrorist who is threatening M personally and the whole of British intelligence. Released for the franchise's fiftieth year, it won two Oscars.","fact":"Adele's title song was the first from a Bond film to win an Oscar; earlier themes had only ever been nominated.","wiki_en":"Skyfall"},{"name":"Die Another Day","emoji":"❄️","meta":["action","2002","Lee Tamahori"],"description":"After long captivity in North Korea, James Bond comes back to duty and investigates the links between a mysterious magnate, the diamond trade and a dangerous weapon built on satellite technology. Made for the franchise's fortieth year, it was Pierce Brosnan's last.","fact":"Bond here gets a car with adaptive camouflage that renders it invisible — one of the most far-fetched gadgets in the series.","wiki_en":"Die Another Day"},{"name":"John Wick: Chapter 2","emoji":"🐺","meta":["action","2017","Chad Stahelski"],"description":"The retired hitman John Wick is forced back into the world of contract killing by an old debt of honour to an Italian crime boss, and the unwritten laws of that world put his own life on the table. The sequel greatly widened the invented universe of assassins.","fact":"Keanu Reeves worked through many of the complicated fight scenes himself, over months of intensive training before filming.","wiki_en":"John Wick: Chapter 2"},{"name":"John Wick: Chapter 3 – Parabellum","emoji":"🐴","meta":["action","2019","Chad Stahelski"],"description":"Declared an outlaw for breaking the sacred rules of the assassins' world, John Wick runs for his life through the streets of New York looking for allies while an enormous bounty sits on his head. The third film digs deeper into that secret international order.","fact":"In one scene John Wick fights off his attackers using library books as weapons — a rare piece of improvised combat.","wiki_en":"John Wick: Chapter 3 – Parabellum"},{"name":"The Little Mermaid","emoji":"🧜‍♀️","meta":["animation","1989","Ron Clements, John Musker"],"description":"The young mermaid Ariel dreams of living among humans and, having fallen for a human prince, makes a dangerous bargain with the sea witch Ursula, trading her voice for a pair of legs. Disney's version of Andersen opened the studio's late-century renaissance.","fact":"The song Under the Sea won an Oscar and became one of the most recognisable Disney tunes of all.","wiki_en":"The Little Mermaid (1989 film)"},{"name":"Beauty and the Beast","emoji":"🌹","meta":["animation","1991","Gary Trousdale, Kirk Wise"],"description":"Belle, a bookish young woman, agrees to stay prisoner in the castle of an enchanted prince turned into a beast in order to free her father, and behind her host's brutal exterior gradually finds a kind soul. It was the first animated feature nominated for best picture.","fact":"The ballroom waltz was made with a three-dimensional computer background — a real technical leap for hand-drawn animation.","wiki_en":"Beauty and the Beast (1991 film)"},{"name":"Aladdin","emoji":"🧞","meta":["animation","1992","Ron Clements, John Musker"],"description":"The street thief Aladdin finds a magic lamp with a genie who can grant any three wishes, and uses them to win the heart of Princess Jasmine by pretending to be a prince. Drawn from the Thousand and One Nights, the film is remembered for its colour and its genie.","fact":"The genie was voiced by the comedian Robin Williams, who improvised a great deal of the character's dialogue in the recording studio.","wiki_en":"Aladdin (1992 Disney film)"},{"name":"Pocahontas","emoji":"🍃","meta":["animation","1995","Mike Gabriel, Eric Goldberg"],"description":"Pocahontas, the daughter of a Native American chief, meets the English colonist Captain John Smith and tries to head off the conflict between her people and the arriving settlers. Disney's film draws on the heavily mythologised story of a real seventeenth-century figure.","fact":"It was Disney's first animated feature whose heroine was based on a real historical person.","wiki_en":"Pocahontas (1995 film)"},{"name":"Mulan","emoji":"⚔️","meta":["animation","1998","Tony Bancroft, Barry Cook"],"description":"Mulan disguises herself as a man and takes her sick father's place in the imperial Chinese army to defend the country against the Hun invasion. Disney's film draws on an ancient Chinese legend and gave the studio one of its first independent warrior heroines.","fact":"The legend of Hua Mulan behind the story is known in China from the Ballad of Mulan, composed some fifteen centuries ago.","wiki_en":"Mulan (1998 film)"},{"name":"Monsters, Inc.","emoji":"👹","meta":["animation","2001","Pete Docter"],"description":"At a factory where monsters frighten children to turn their screams into power, the good-natured giant Sulley and his one-eyed partner Mike accidentally let a little girl into their world, breaking every rule of monster society. Pixar turns childhood fears inside out.","fact":"Animating Sulley's fur realistically required a dedicated hair simulation technology, later used in other Pixar films.","wiki_en":"Monsters, Inc."},{"name":"The Incredibles","emoji":"🦸‍♀️","meta":["animation","2004","Brad Bird"],"description":"A family of former superheroes, forced to hide their powers and live ordinary lives since heroics were outlawed, goes back to saving the world when a cunning villain starts moving against them. Pixar's film was one of the first to take the superhero genre seriously.","fact":"It was Pixar's first feature with mainly human characters, rather than toys, insects or animals.","wiki_en":"The Incredibles"},{"name":"Cars","emoji":"🏎️","meta":["animation","2006","John Lasseter"],"description":"The arrogant race car Lightning McQueen, on his way to an important competition, gets stuck in a small town on the legendary Route 66 and slowly learns to value friendship and respect above personal glory. The film is set in a world inhabited entirely by living cars.","fact":"The designers took real road trips along historic Route 66 to capture the feel of America's small roadside towns.","wiki_en":"Cars (film)"},{"name":"Ratatouille","emoji":"🐀","meta":["animation","2007","Brad Bird"],"description":"Remy, a rat with a fine nose and a dream of becoming a chef, secretly helps a hopeless kitchen assistant cook haute cuisine in a grand Paris restaurant, steering him from under his hat. The film ties food to a tender story about the right to a dream.","fact":"The studio's animators did stints in professional kitchens so that the cooking would look right.","wiki_en":"Ratatouille (film)"},{"name":"Inside Out","emoji":"🧠","meta":["animation","2015","Pete Docter"],"description":"Inside the head of a girl called Riley live her emotions in person — Joy, Sadness, Anger, Fear and Disgust — coping with the family's move to a new city and with their owner growing up. Pixar's film gives the workings of the mind and memory an unusual shape.","fact":"The makers consulted working psychologists and neuroscientists to give emotion and memory a plausible design.","wiki_en":"Inside Out (2015 film)"},{"name":"Zootopia","emoji":"🦊","meta":["animation","2016","Byron Howard, Rich Moore"],"description":"The determined rabbit Judy Hopps becomes the first of her kind on the police force of a city of animals, and has to team up with a sly fox conman to crack a strange case of missing citizens. Disney's film takes on prejudice and stereotype through a satirical animal world.","fact":"The designers gave each district of Zootopia its own architecture, scaled for animals from mice to elephants.","wiki_en":"Zootopia"},{"name":"Moana","emoji":"🌊","meta":["animation","2016","Ron Clements, John Musker"],"description":"Moana, the daughter of a Polynesian island chief, sets out on a dangerous ocean voyage with the demigod Maui to return the heart of a nature goddess that he stole, and save her people from disaster. Disney drew on the myth and seafaring of the Pacific islands.","fact":"The makers spent years consulting historians, anthropologists and navigators of Oceania to get the culture right.","wiki_en":"Moana (2016 film)"},{"name":"Tangled","emoji":"👱‍♀️","meta":["animation","2010","Nathan Greno, Byron Howard"],"description":"A girl with magical hair of impossible length, shut in a high tower by a witch for years, leaves her hiding place for the first time with the help of a charming thief, to see the lights she watches from her window each year. Disney's take on the Brothers Grimm.","fact":"Animating Rapunzel's long, flowing hair took the studio's artists an extraordinary amount of time and a simulation technology of its own.","wiki_en":"Tangled"},{"name":"Wreck-It Ralph","emoji":"🕹️","meta":["animation","2012","Rich Moore"],"description":"Ralph, the villain of an old video game, tires of being the bad guy and travels through the other games in the arcade cabinet looking for a medal to prove he can be good too. Disney's film plays wittily with the look and the characters of classic video games.","fact":"Recognisable characters from real video games appear as cameos, among them the heroes of Sonic the Hedgehog and Pac-Man.","wiki_en":"Wreck-It Ralph"},{"name":"How to Train Your Dragon","emoji":"🐉","meta":["animation","2010","Dean DeBlois, Chris Sanders"],"description":"Hiccup, a young Viking in a village of dragon hunters, secretly tames a wounded black dragon instead of killing it, and discovers that dragons are nothing like the monsters his people believe them to be. DreamWorks made one of the warmest films about that friendship.","fact":"In building Toothless, the animators borrowed the habits of cats and other real animals to make the dragon feel supple and alive.","wiki_en":"How to Train Your Dragon (2010 film)","wiki_ru":"Как приручить дракона"},{"name":"Madagascar","emoji":"🦒","meta":["animation","2005","Eric Darnell, Tom McGrath"],"description":"Four animals from a New York zoo — a lion, a zebra, a giraffe and a hippo — end up on the wild island of Madagascar and have to learn to survive without the comforts of the enclosure. DreamWorks's film is remembered for its characters and began a popular series.","fact":"Some of its characters, especially the irrepressible penguins, proved so popular that they later got series and spin-offs of their own.","wiki_en":"Madagascar (2005 film)"},{"name":"Kung Fu Panda","emoji":"🐼","meta":["animation","2008","Mark Osborne, John Stevenson"],"description":"Po, a clumsy, lazy panda working in his father's noodle shop, is unexpectedly chosen as the legendary Dragon Warrior and has to master martial arts under a strict teacher to defend the valley from a dangerous villain. DreamWorks mixes comedy with classic kung fu cinema.","fact":"The makers consulted real martial arts masters so that the animated characters' movements would be technically sound.","wiki_en":"Kung Fu Panda (film)","wiki_ru":"Кунг-фу панда"},{"name":"The Nightmare Before Christmas","emoji":"🎃","meta":["animation","1993","Henry Selick"],"description":"Jack Skellington, the king of Halloween, tired of frightening people year after year, stumbles on a magic doorway into the world of Christmas and decides to run the holiday his own way, mixing the ghoulish in with the kind. Produced by Tim Burton, it became a cult classic.","fact":"The whole film is stop-motion puppet animation, and several hundred interchangeable heads were made for Jack Skellington's expressions.","wiki_en":"The Nightmare Before Christmas"},{"name":"Ice Age","emoji":"🐿️","meta":["animation","2002","Chris Wedge"],"description":"A mammoth, a sloth and a sabre-toothed tiger from the ice age, who distrust each other from the start, join forces to return a human baby to its tribe, and slowly become an unlikely but solid family. Blue Sky Studios's film began a long-running comic franchise.","fact":"The minor character Scrat, the squirrel forever chasing an acorn, never says a word and became one of the franchise's main emblems.","wiki_en":"Ice Age (2002 film)"},{"name":"Despicable Me","emoji":"🍌","meta":["animation","2010","Pierre Coffin, Chris Renaud"],"description":"Gru, a villain who keeps failing, plots to steal the Moon and adopts three orphan girls to use in his scheme, only to grow genuinely attached to them. The film introduced audiences to the tiny yellow minions, who became a pop phenomenon in their own right.","fact":"The minions, meant as minor characters, later got a film franchise of their own that made even more money than the original.","wiki_en":"Despicable Me (film)"},{"name":"Three from Prostokvashino","emoji":"🐱","meta":["animation","1978","Vladimir Popov"],"description":"A boy nicknamed Uncle Fyodor goes off to live in a village house in Prostokvashino with the talking cat Matroskin and the good-natured dog Sharik, where the three of them keep house and get into small, funny scrapes. A much-loved Soviet family classic.","fact":"Matroskin's line \"to sell something useless, you first have to buy something useless\" long ago became an everyday saying.","wiki_en":"Three from Prostokvashino","wiki_ru":"Трое из Простоквашино"},{"name":"Winnie-the-Pooh","emoji":"🍯","meta":["animation","1969","Fyodor Khitruk"],"description":"The first of the Soviet films about the bear with sawdust in his head, who goes after honey with his friend Piglet by pretending to be a little cloud. Fyodor Khitruk's adaptation of A. A. Milne created a Pooh of its own, quite unlike the Disney version.","fact":"Pooh was voiced by Yevgeny Leonov, whose distinctive tone became inseparable from the bear for several generations.","wiki_en":"Winnie-the-Pooh (1969 film)","wiki_ru":"Винни-Пух (мультфильм)"},{"name":"Hedgehog in the Fog","emoji":"🦔","meta":["animation","1975","Yuri Norstein"],"description":"A little hedgehog sets off to visit his friend Bear Cub and count the stars, but loses his way in a thick fog, where he meets strange and frightening shapes. Yuri Norstein's film has repeatedly been named by critics among the finest animated works ever made.","fact":"To build the thick fog, the animators shot in layers, using several sheets of semi-transparent tracing paper.","wiki_en":"Hedgehog in the Fog"},{"name":"There Once Was a Dog","emoji":"🐺","meta":["animation","1982","Eduard Nazarov"],"description":"An old dog thrown out by his owners meets a wolf in the forest who, instead of eating him, offers an unexpected plan to save him, and an odd friendship begins. This short film, from a Ukrainian folk tale, is known for its dry humour and its endlessly quoted lines.","fact":"The wolf's \"Now I'll sing for you\" has long since turned into a standing joke in everyday Russian speech.","wiki_en":"Once Upon a Dog"},{"name":"The Bremen Town Musicians","emoji":"🎸","meta":["animation","1969","Inessa Kovalevskaya"],"description":"A band of travelling animal musicians led by the charming Troubadour wanders the roads of a fairy-tale kingdom and helps the Princess escape the rule of a tyrannical king. This Soviet musical version of the Brothers Grimm is famous for its rock and roll songs.","fact":"Almost every song was performed by one man, Oleg Anofriev, who also voiced the Troubadour and most of the other characters.","wiki_en":"The Bremen Town Musicians (1969 film)","wiki_ru":"Бременские музыканты (мультфильм)"},{"name":"The Flying Ship","emoji":"⛵","meta":["animation","1979","Garri Bardin"],"description":"Ivan, a poor but resourceful village lad, builds a magic flying ship with the help of a band of fairy-tale characters in order to win the tsar's daughter against the scheming of the boastful Polkan. Adapted from a Russian folk tale, it is remembered for its songs.","fact":"The song of the Baba Yagas from this film is still often performed at children's parties as a recognisable comic turn.","wiki_en":"The Flying Ship (animated film)","wiki_ru":"Летучий корабль (мультфильм)"},{"name":"The Snow Queen","emoji":"❄️","meta":["animation","1957","Lev Atamanov"],"description":"The girl Gerda sets out on a dangerous journey through the cold northern lands to find and rescue her friend Kai, whose heart has been frozen by the treacherous Snow Queen. This Soviet version of Hans Christian Andersen is a summit of hand-drawn animation.","fact":"The film made an enormous impression on the Japanese animator Hayao Miyazaki, who later named it as a source of his own inspiration.","wiki_en":"The Snow Queen (1957 film)"},{"name":"The Twelve Months","emoji":"🔥","meta":["animation","1956","Ivan Ivanov-Vano, Mikhail Botov"],"description":"A wilful little queen demands snowdrops in midwinter, and her stepmother's stepdaughter is sent into the freezing forest, where she finds all twelve months of the year gathered around a magic fire. From a play by Samuil Marshak, it is a New Year classic.","fact":"Each of the twelve months in the film was given a look and a character of its own, matched to its season.","wiki_en":"The Twelve Months (1956 film)","wiki_ru":"Двенадцать месяцев (мультфильм)"},{"name":"Cheburashka","emoji":"🐵","meta":["animation","1971","Roman Kachanov"],"description":"A mysterious big-eared creature unknown to science, found in a crate of oranges, looks for friends together with Gena the crocodile, helps everyone around him and foils the schemes of the spiteful old Shapoklyak. The puppet film made Cheburashka a Soviet icon.","fact":"Cheburashka caught on so widely that he was later the official mascot of the Russian team at several Olympic Games.","wiki_en":"Cheburashka (1971 film)","wiki_ru":"Чебурашка (мультфильм, 1971)"},{"name":"Kin-dza-dza!","emoji":"🛸","meta":["science fiction","1986","Georgiy Daneliya"],"description":"A building foreman and a student who happens to be standing next to him are carried off by an alien's strange device to the desert planet Plyuk in another galaxy, where they have to learn absurd social rules. Daneliya's satirical fable mocks human hierarchies.","fact":"The invented word \"ku\", which on Plyuk stands in for almost everything one might say, became a catchphrase in Russian.","wiki_en":"Kin-dza-dza!"},{"name":"Heart of a Dog","emoji":"🐕","meta":["tragicomedy","1988","Vladimir Bortko"],"description":"Professor Preobrazhensky transplants a human pituitary gland into a stray dog, and the dog gradually turns into a coarse, insolent man called Sharikov who brings the professor nothing but trouble. This adaptation of Bulgakov is one of Soviet television's finest.","fact":"The professor's line \"the ruin is not in the lavatories, it is in people's heads\" has long since taken on a life of its own.","wiki_en":"Heart of a Dog (1988 film)","wiki_ru":"Собачье сердце (фильм, 1988)"},{"name":"Only Old Men Are Going into Battle","emoji":"✈️","meta":["war drama","1973","Leonid Bykov"],"description":"A veteran fighter pilot known as the Maestro builds a squadron out of untested newcomers and turns it into the famous \"singing\" squadron, trying to keep his boys human in the middle of a war. Leonid Bykov, who also starred, made a much-loved Soviet film.","fact":"Bykov was a passionate lover of aviation and was not only director and lead but also co-author of the screenplay.","wiki_en":"Only \"Old Men\" Are Going Into Battle","wiki_ru":"В бой идут одни «старики»"},{"name":"Officers","emoji":"🎖️","meta":["war drama","1971","Vladimir Rogovoy"],"description":"The film follows two officer friends and the woman they both love across several decades of Soviet history, from the Civil War to the Second World War, showing how honour and friendship survive every trial. It became the model film about generations in uniform.","fact":"The line \"there is such a profession: defending the motherland\" is one of the best-known quotations in Soviet cinema.","wiki_en":"Officers (film)","wiki_ru":"Офицеры (фильм)"},{"name":"The Dawns Here Are Quiet","emoji":"🌲","meta":["war drama","1972","Stanislav Rostotsky"],"description":"A sergeant major at a small anti-aircraft post takes a detachment of young women gunners into the forests of Karelia to track a group of German saboteurs, and the fragile squad accepts an impossible fight. Adapted from Boris Vasilyev, it is a piercing film about women at war.","fact":"It won wide international recognition and was nominated for the Oscar for best foreign language film.","wiki_en":"The Dawns Here Are Quiet (1972 film)","wiki_ru":"А зори здесь тихие (фильм, 1972)"},{"name":"Destiny of a Man","emoji":"🎖️","meta":["war drama","1959","Sergei Bondarchuk"],"description":"The former front-line soldier Andrei Sokolov tells a chance travelling companion the story of his life: captivity, the loss of his family, and finding a reason to go on after the war. Bondarchuk's directing debut was one of the first Soviet films to face the fate of prisoners of war honestly.","fact":"Sergei Bondarchuk both directed and played the lead, creating a figure that came to stand for ordinary endurance.","wiki_en":"Destiny of a Man","wiki_ru":"Судьба человека (фильм)"},{"name":"The Cranes Are Flying","emoji":"🕊️","meta":["war drama","1957","Mikhail Kalatozov"],"description":"A young couple is parted when the man volunteers for the front, and the woman left behind must live through bombing, loss and a hard moral choice. Mikhail Kalatozov's film remains the only Soviet picture ever to win the top prize at Cannes.","fact":"The cinematographer Sergei Urusevsky shot several scenes with methods well ahead of their time, including long unbroken moving takes.","wiki_en":"The Cranes Are Flying"},{"name":"Ballad of a Soldier","emoji":"🎗️","meta":["war drama","1959","Grigori Chukhrai"],"description":"A young soldier is given a short leave for knocking out an enemy tank and sets off to see his mother, but on the way he keeps meeting people who need help, so that only minutes are left for the meeting itself. A simple, moving classic of Soviet war cinema.","fact":"The film won a special prize at Cannes and was nominated for the Oscar for best original screenplay.","wiki_en":"Ballad of a Soldier"},{"name":"Ivan's Childhood","emoji":"🌒","meta":["war drama","1962","Andrei Tarkovsky"],"description":"Ivan, a boy who lost his family in the war, becomes a young scout and goes back through the front line again and again, however hard the older officers try to keep him out of danger. Andrei Tarkovsky's first feature won the Golden Lion at Venice.","fact":"Tarkovsky came to the project after another director had already begun shooting, and remade the film almost entirely to his own vision.","wiki_en":"Ivan's Childhood"},{"name":"Andrei Rublev","emoji":"🎨","meta":["historical drama","1966","Andrei Tarkovsky"],"description":"In a series of episodes the film traces the life and spiritual searching of the medieval icon painter Andrei Rublev against the cruel princely feuds and Tatar raids of old Rus. Tarkovsky's vast, philosophical picture is one of the summits of world cinema.","fact":"Because of a difficult passage through censorship, the full authorial version only reached wide Soviet release some years after filming ended.","wiki_en":"Andrei Rublev (film)"},{"name":"Mirror","emoji":"🪞","meta":["drama","1975","Andrei Tarkovsky"],"description":"Tarkovsky's autobiographical and deliberately non-linear film joins memories of childhood, dreams and the upheavals of the twentieth century into a single poetic stream of images instead of a plot. It is among his most personal and formally daring works.","fact":"The same actress plays the hero's mother at different ages and his wife, which deepens the sense of times folding into one another.","wiki_en":"Mirror (1975 film)"},{"name":"Solaris","emoji":"🪐","meta":["science fiction","1972","Andrei Tarkovsky"],"description":"A psychologist travels to an orbital station above the enigmatic ocean planet Solaris, where the crew is haunted by apparitions that make their deepest memories and guilt material. Tarkovsky's version of Stanisław Lem cares more about inner life than about the future's technology.","fact":"Tarkovsky deliberately cut down the futuristic sets and technical detail, to shift the weight from science fiction to human drama.","wiki_en":"Solaris (1972 film)"},{"name":"Assa","emoji":"🎸","meta":["drama","1987","Sergei Solovyov"],"description":"A young woman who comes to wintry Yalta with the crime boss Krymov falls for the odd young musician Bananan, and their story unfolds against the rock culture waking up in the perestroika years. Solovyov's film became the emblem of the late 1980s.","fact":"Songs by the band Kino run through the film, and at the end Viktor Tsoi himself appears, performing the anthem Changes.","wiki_en":"Assa (film)"},{"name":"The Needle","emoji":"💉","meta":["drama","1988","Rashid Nugmanov"],"description":"A young man nicknamed Moro comes back to his home town and tries to pull his former girlfriend out of drug addiction, taking on the people making money from her trouble. A landmark of the Kazakh new wave, it became a cult film largely thanks to Viktor Tsoi.","fact":"Part of the film was shot on the dried-up Aral Sea, and the shots of abandoned ships in the sand are its most haunting images.","wiki_en":"The Needle (1988 film)"},{"name":"The Irony of Fate 2","emoji":"🥂","meta":["romantic comedy","2007","Timur Bekmambetov"],"description":"Three decades after the New Year's Eve of the classic film, the children of its characters accidentally repeat their parents' fate, caught up in a similar holiday mix-up in modern Moscow. The sequel moved a much-loved Soviet plot into the twenty-first century.","fact":"Actors from the original film returned in the sequel, playing older versions of their own characters.","wiki_en":"Irony of Fate 2","wiki_ru":"Ирония судьбы. Продолжение"},{"name":"Garage","emoji":"🚗","meta":["tragicomedy","1979","Eldar Ryazanov"],"description":"A meeting of the co-operative that allocates garage spaces turns into an all-night war in which apparently respectable research institute staff lay bare every petty compromise and hypocrisy they have. Ryazanov's satire plays out almost entirely in one room.","fact":"Eldar Ryazanov himself plays a silent institute employee who sleeps peacefully on a stuffed animal through nearly the whole uproar.","wiki_en":"The Garage (1980 film)","wiki_ru":"Гараж (фильм)"},{"name":"Autumn Marathon","emoji":"🍂","meta":["tragicomedy","1979","Georgiy Daneliya"],"description":"A gentle, indecisive translator is pulled between his wife, his lover and everyone else's endless requests, unable to refuse any of them, and slowly turns his own kindness into a source of misery for all. Daneliya balances comedy against real everyday drama.","fact":"The line \"we're having a nice time here\" from this film long ago left it and lives on by itself in Russian.","wiki_en":"Autumn Marathon"},{"name":"Station for Two","emoji":"🚉","meta":["romance","1982","Eldar Ryazanov"],"description":"A pianist from the capital, facing trial for something he did not do, misses his train and meets the waitress of a provincial station buffet, and an awkward but honest relationship grows between them. Ryazanov blends lyricism with sharp satire of Soviet life.","fact":"The buffet waitress is one of Lyudmila Gurchenko's defining roles, holding comedy and drama in one character.","wiki_en":"Station for Two"},{"name":"Mimino","emoji":"🚁","meta":["tragicomedy","1977","Georgiy Daneliya"],"description":"A Georgian pilot who flies a small helicopter between mountain villages dreams of a big aircraft and goes off to conquer Moscow, where he unexpectedly makes friends with an Armenian long-haul driver. Daneliya's warm comedy is among the best-loved Soviet films.","fact":"Rubik's line \"that's what I think!\" became so famous that people recognise it even without having seen the film.","wiki_en":"Mimino","wiki_ru":"Мимино"},{"name":"Afonya","emoji":"🔧","meta":["tragicomedy","1975","Georgiy Daneliya"],"description":"A plumber known as Afonya leads a dissolute bachelor life, cutting corners on call-outs and drinking the money away, until a chain of chance encounters makes him think about his own loneliness and the emptiness of it. Daneliya mixes domestic humour with a sad moral.","fact":"Afonya is one of the most recognisable roles of Leonid Kuravlyov, a fixture of the Soviet comedies of those years.","wiki_en":"Afonya","wiki_ru":"Афоня"},{"name":"Air Crew","emoji":"🛫","meta":["disaster film","1979","Alexander Mitta"],"description":"Three crew members of a civil airliner, with very different characters and private troubles, face a real catastrophe when a devastating earthquake breaks out in the distant city they have flown to for the injured. One of the first Soviet disaster films.","fact":"A real decommissioned airliner was used for the scenes with the damaged plane, not only models and sets.","wiki_en":"Air Crew","wiki_ru":"Экипаж (фильм, 1979)"},{"name":"Pirates of the 20th Century","emoji":"🏴‍☠️","meta":["action","1979","Boris Durov"],"description":"The crew of a Soviet merchant ship is attacked by modern pirate smugglers after a cargo of opium, and the sailors have to fight well-armed bandits. One of the first Soviet action films with martial arts, it hit audiences like a bombshell.","fact":"It became one of the highest-grossing films in Soviet cinema history, largely thanks to hand-to-hand fights nobody there had seen before.","wiki_en":"Pirates of the 20th Century","wiki_ru":"Пираты XX века"},{"name":"Amphibian Man","emoji":"🐟","meta":["science fiction","1961","Gennadi Kazansky, Vladimir Chebotaryov"],"description":"Ichthyander, given shark's gills as a child, can live freely on land and under water, but he falls in love with an ordinary girl and must choose between the two worlds. Adapted from Alexander Belyaev, it was among the first Soviet films with large-scale underwater photography.","fact":"The underwater scenes were shot in the Black Sea without modern diving gear, which made them genuinely risky for the actors.","wiki_en":"Amphibian Man (film)","wiki_ru":"Человек-амфибия (фильм)"},{"name":"The Adventures of Elektronik","emoji":"🤖","meta":["science fiction","1979","Konstantin Bromberg"],"description":"A scientist builds a schoolboy robot, Elektronik, indistinguishable from a real boy called Sergei Syroyezhkin, and when the robot escapes the laboratory a chain of mix-ups and adventures with the two doubles begins. A favourite Soviet children's television film.","fact":"The song The Winged Swings from this film became one of the best-known children's songs of the Soviet era.","wiki_en":"The Adventures of Elektronik","wiki_ru":"Приключения Электроника"},{"name":"The Twelve Chairs","emoji":"🪑","meta":["comedy","1971","Leonid Gaidai"],"description":"The former nobleman Ippolit Vorobyaninov and the smooth chancer Ostap Bender go hunting for the family diamonds hidden in one of a set of twelve chairs, sold off across the country after the revolution. Adapted from Ilf and Petrov, it is a classic Ostap Bender comedy.","fact":"Ostap Bender is played here by Archil Gomiashvili, though other well-known actors have given their own versions of the character.","wiki_en":"The Twelve Chairs (1971 film)"},{"name":"It Can't Be!","emoji":"🎭","meta":["comedy","1975","Leonid Gaidai"],"description":"Three separate comic stories, taken from the early humorous writing of Mikhail Zoshchenko, in which hapless Soviet citizens land themselves in ridiculous domestic scrapes through their own cunning or greed. Gaidai assembled another all-star cast for this portmanteau comedy.","fact":"All three stories play out in the 1920s of the New Economic Policy, the very era Zoshchenko wrote about.","wiki_en":"It Can't Be!","wiki_ru":"Не может быть! (фильм)"},{"name":"Sportloto-82","emoji":"🎟️","meta":["comedy","1982","Leonid Gaidai"],"description":"A young man on holiday at a Black Sea resort loses a lottery ticket with a large prize on it and sets off with a new acquaintance to find it, while a slippery black-market dealer is on the trail of the same ticket. One of Gaidai's late comedies, still briskly funny.","fact":"The title refers to the real Soviet lottery Sportloto, whose tickets were bought all over the country at the time.","wiki_en":"Sportloto-82","wiki_ru":"Спортлото-82"},{"name":"Pokrovsky Gates","emoji":"🏙️","meta":["comedy","1982","Mikhail Kozakov"],"description":"This warm, nostalgic comedy plays out in a communal flat in the Pokrovsky Gates district of mid-1950s Moscow, where the lives and love affairs of several colourful neighbours run into one another. Kozakov's television film is among the most rewatched Soviet comedies.","fact":"Modestly received on its first broadcast, it grew into a cult favourite and has been shown on television ever since.","wiki_en":"Pokrovsky Gates","wiki_ru":"Покровские ворота (фильм)"},{"name":"The Formula of Love","emoji":"🪄","meta":["comedy","1984","Mark Zakharov"],"description":"The mysterious Count Cagliostro, rumoured to hold magical powers and the formula of eternal youth, arrives at a Russian country estate at the end of the eighteenth century, and the local gentry promptly put him to their own selfish uses. A wry costume comedy.","fact":"The line \"do you want a great love, but a pure one?\" from this film long ago became an ironic saying of its own.","wiki_en":"The Formula of Love","wiki_ru":"Формула любви"},{"name":"The Very Same Munchhausen","emoji":"🎈","meta":["comedy","1979","Mark Zakharov"],"description":"The legendary Baron Munchhausen tries to convince a starchy German society that his incredible adventures really happened, and runs into the bureaucratic demand that he prove his own identity through the proper channels. Zakharov turns a tall tale into a parable about conformity.","fact":"Munchhausen's \"Smile, gentlemen, smile\" is one of the most quoted lines in Soviet television cinema.","wiki_en":"The Very Same Munchhausen","wiki_ru":"Тот самый Мюнхгаузен"},{"name":"An Ordinary Miracle","emoji":"🐻","meta":["fairy tale","1978","Mark Zakharov"],"description":"A wizard living far from people turns a bear into a handsome young man, but warns him that he will become a beast again if a princess in love with him kisses him — and then watches the love story unfold. Adapted from Yevgeny Schwartz, it is romance and philosophy at once.","fact":"The music was written by Gennady Gladkov and the lyrics by Yuly Kim, who at the time had to publish under a pseudonym.","wiki_en":"An Ordinary Miracle (1978 film)","wiki_ru":"Обыкновенное чудо (фильм, 1978)"},{"name":"Hello, I'm Your Aunt!","emoji":"👒","meta":["comedy","1975","Viktor Titov"],"description":"The vagrant Babs Baberley, having wandered into the rooms of two Oxford students, agrees to impersonate their rich aunt from Brazil, \"where there are lots and lots of wild monkeys in the forests\", and the small lie snowballs into farce. From the classic English stage comedy.","fact":"The lead is played by Alexander Kalyagin, whose gift for eccentric physical comedy made this one of his most memorable parts.","wiki_en":"Hello, I'm Your Aunt!","wiki_ru":"Здравствуйте, я ваша тётя!"},{"name":"Morozko","emoji":"❄️","meta":["fairy tale","1964","Alexander Rou"],"description":"A capricious stepmother's daughter and the kind orphan Nastenka both meet Morozko, the stern spirit of the winter forest, who tests each of them for kindness and hard work before rewarding or punishing her accordingly. A classic Soviet film fairy tale, and a New Year fixture.","fact":"In the United States it was released as Jack Frost and later became the target of good-natured mockery on a cult show about odd films.","wiki_en":"Jack Frost (1964 film)","wiki_ru":"Морозко (фильм, 1964)"},{"name":"The Adventures of Buratino","emoji":"🪵","meta":["musical fairy tale","1975","Leonid Nechayev"],"description":"Buratino, a wooden boy carved by Papa Carlo out of a log, sets off for school but gives in on the way to the temptations of Basilio the cat and Alisa the fox, landing in a string of dangerous and funny adventures in search of a golden key. A children's classic.","fact":"The songs from this film, including the famous Buratino, have long been a staple of children's parties across the country.","wiki_en":"The Adventures of Buratino (1975 film)","wiki_ru":"Приключения Буратино (фильм)"},{"name":"Scarecrow","emoji":"🎒","meta":["drama","1983","Rolan Bykov"],"description":"A new girl in a school class takes the blame for something she did not do and becomes the target of cruel bullying by her classmates, left to get through it alone. One of the first Soviet films to show school bullying openly, it caused a public stir on release.","fact":"The lead was played by the twelve-year-old Kristina Orbakaite, for whom the film was a screen debut.","wiki_en":"Scarecrow (1984 film)","wiki_ru":"Чучело (фильм)"},{"name":"Courier","emoji":"📮","meta":["tragicomedy","1986","Karen Shakhnazarov"],"description":"A school leaver who failed to get into university takes a job as a courier at a magazine, and his ironic, faintly insolent manner baffles the adults around him, who are used to other rules. Shakhnazarov's film caught the mood of Soviet youth in the perestroika years.","fact":"The lead was played by Fyodor Dunayevsky, for whom it was one of the few notable roles of a short screen career.","wiki_en":"Courier (film)","wiki_ru":"Курьер (фильм, 1986)"},{"name":"Little Vera","emoji":"🏭","meta":["drama","1988","Vasili Pichul"],"description":"A young woman from a factory family in a provincial industrial town tries to break out of a crushing daily routine and constant conflict with her parents through a relationship with a young man. It was one of the first Soviet films to speak openly about young people's lives.","fact":"It was shot in Zhdanov, today's Mariupol, and the factory edges of the town became almost a character in their own right.","wiki_en":"Little Vera"},{"name":"Viy","emoji":"👹","meta":["horror","1967","Konstantin Yershov, Georgi Kropachyov"],"description":"A young seminarian who has accidentally caused a witch's death is obliged to read over her coffin in an old church for three nights running, and with each night the forces from the other side press harder. Adapted from Gogol, it is the first horror feature made in the Soviet Union.","fact":"To build the monster Viy and the other creatures, the crew used make-up and mechanical rigs that were complex for their time.","wiki_en":"Viy (1967 film)"},{"name":"Night Watch","emoji":"🌙","meta":["fantasy","2004","Timur Bekmambetov"],"description":"A centuries-old war between the forces of Light and Darkness runs through modern Moscow, hidden from ordinary people, and a Muscovite named Anton, discovering that he is an Other, ends up at the centre of it on the side of the Light. From the novel by Sergei Lukyanenko.","fact":"It set the box-office record for a Russian film at the time, ahead of many Hollywood releases of that year.","wiki_en":"Night Watch (2004 film)"},{"name":"Day Watch","emoji":"☀️","meta":["fantasy","2006","Timur Bekmambetov"],"description":"The story of the war between Light and Darkness in Moscow moves up a level when an ancient artefact enters play, one capable of rewriting the fate of the world itself. The sequel to Night Watch pushed the effects and the spectacle of the first film further still.","fact":"Some of the final scenes were shot in real Moscow locations, transformed by computer graphics.","wiki_en":"Day Watch (film)","wiki_ru":"Дневной Дозор (фильм)"},{"name":"9th Company","emoji":"🪖","meta":["war drama","2005","Fyodor Bondarchuk"],"description":"A group of young conscripts goes through brutal training before being sent to Afghanistan, and then finds itself on a remote hilltop that the Soviet unit has to hold against a far stronger enemy. Bondarchuk's film is among the best-known Russian films about that war.","fact":"The plot is based on the real battle for Hill 3234, fought in Afghanistan in 1988.","wiki_en":"9th Company"},{"name":"T-34","emoji":"🪖","meta":["war drama","2018","Alexei Sidorov"],"description":"A young Soviet tank driver is taken prisoner by the Germans, and years later is made to test a captured T-34 against an experienced German crew — which gives him an unexpected chance at an audacious escape. One of the highest-grossing Russian war films.","fact":"Several full-size working replicas of T-34s and of German vehicles of the period were built for the shoot.","wiki_en":"T-34 (film)","wiki_ru":"Т-34 (фильм)"},{"name":"Three Seconds","emoji":"🏀","meta":["sports drama","2017","Anton Megerdichev"],"description":"The film recreates the legendary basketball final of the 1972 Summer Olympics between the USSR and the United States, one of the most dramatic and most argued-over games in the history of the sport. It became one of the biggest Russian box-office hits of its time.","fact":"Commentators still regularly recall the closing seconds of that Olympic final as one of the tensest moments in basketball.","wiki_en":"Going Vertical","wiki_ru":"Движение вверх (фильм)"},{"name":"Legend No. 17","emoji":"🏒","meta":["sports drama","2013","Nikolai Lebedev"],"description":"The film follows the making of the legendary Soviet ice hockey player Valeri Kharlamov, his hard road into the top of the game and his clash with the star-studded Canadian team in the historic Summit Series of 1972. One of the most successful Russian sports films.","fact":"The training camp where the actors prepared for the hockey scenes was run by real professional hockey coaches.","wiki_en":"Legend No. 17","wiki_ru":"Легенда №17"},{"name":"Viking","emoji":"⚔️","meta":["historical drama","2016","Andrei Kravchuk"],"description":"The film covers the early reign of Prince Vladimir Svyatoslavich, his struggle for the throne of Kiev and the fateful choice of a new faith for old Rus that followed. Andrei Kravchuk's historical epic was one of the most expensive Russian productions of its day.","fact":"Sets of ancient Kiev were built for the battle scenes, with hundreds of stunt performers and extras.","wiki_en":"Viking (2016 film)"},{"name":"Stalingrad","emoji":"🏚️","meta":["war drama","2013","Fyodor Bondarchuk"],"description":"A small group of Soviet soldiers digs in inside a half-ruined house on the approaches to the Volga during the battle of Stalingrad and, together with a young woman still living there, tries to hold the position. It was one of the first Russian blockbusters shot in IMAX 3D.","fact":"The film was Russia's entry for the Oscar for best foreign language film.","wiki_en":"Stalingrad (2013 film)"},{"name":"The Fool","emoji":"🏚️","meta":["social drama","2014","Yuri Bykov"],"description":"A plumber finds a crack in an old workers' hostel that means the building is about to collapse, and spends one night trying to persuade indifferent officials to evacuate hundreds of residents, running into a wall of corruption. Yuri Bykov's film won festival recognition.","fact":"The whole film takes place over a single night, almost in real time, which tightens the sense of mounting pressure.","wiki_en":"The Fool (2014 film)"},{"name":"Arrhythmia","emoji":"❤️‍🩹","meta":["drama","2017","Boris Khlebnikov"],"description":"An ambulance doctor who gives everything to his patients but is emotionally spent by the work teeters on the edge of divorce from his wife, also a doctor, trying to hold on to both the job and the marriage. Boris Khlebnikov's film won the top prize at Kinotavr.","fact":"Many of the ambulance call-out scenes were shot with real doctors advising, to get the texture of the work right.","wiki_en":"Arrhythmia (film)"},{"name":"Loveless","emoji":"🏚️","meta":["drama","2017","Andrey Zvyagintsev"],"description":"A couple in the middle of a bitter divorce, absorbed in mutual blame and in new relationships, notice too late that their son has gone missing from home. Zvyagintsev's drama won the jury prize at Cannes and an Oscar nomination for best foreign language film.","fact":"It is one of the most decorated Russian films on the international festival circuit of the past decade.","wiki_en":"Loveless (film)"},{"name":"Leviathan","emoji":"🐋","meta":["drama","2014","Andrey Zvyagintsev"],"description":"A car mechanic in a small coastal town takes on the corrupt local mayor, who is trying to take his house and his land, and the losing fight gradually destroys his whole life. Zvyagintsev's drama won a Golden Globe and an Oscar nomination for best foreign language film.","fact":"The title points both to the biblical monster and to Thomas Hobbes's treatise of the same name on the nature of state power.","wiki_en":"Leviathan (2014 film)"},{"name":"Elena","emoji":"🏢","meta":["drama","2011","Andrey Zvyagintsev"],"description":"A middle-aged woman married to a well-off man from another social world faces a hard moral choice when her grown son from a first marriage badly needs money and her husband has no intention of helping. The film won a special prize in Un Certain Regard at Cannes.","fact":"Critics singled out its deliberately restrained, almost documentary manner, with no surplus music or grandeur.","wiki_en":"Elena (2011 film)"},{"name":"The Return","emoji":"🚤","meta":["drama","2003","Andrey Zvyagintsev"],"description":"Two teenage brothers who grew up without a father suddenly meet him again after a long absence, and he takes them on a mysterious trip to a distant lake that slowly lays bare the difficult nature of their bond. Zvyagintsev's debut won the Golden Lion at Venice.","fact":"It is a rare case of a director's first feature taking the top prize at one of Europe's three great festivals straight away.","wiki_en":"The Return (2003 film)"},{"name":"Cargo 200","emoji":"🚔","meta":["drama","2007","Alexei Balabanov"],"description":"In a late-Soviet provincial town a brutal police officer abducts a young woman, and her fate is bound up with the collapse of moral order in a dying era. Balabanov's bleak, deliberately shocking drama caused furious argument on release for its unsparing picture of the period.","fact":"The title is the army code \"cargo 200\", used in the Soviet system for the transport of the bodies of dead servicemen.","wiki_en":"Cargo 200 (film)","wiki_ru":"Груз 200 (фильм)"},{"name":"Dead Man's Bluff","emoji":"🔫","meta":["black comedy","2005","Alexei Balabanov"],"description":"Two small-time crooks in a provincial town in the 1990s try to pull off a deal involving a suitcase of drugs, and the simple job turns into a chain of absurd, bloody misunderstandings with other gangs. Balabanov's black comedy makes grotesque fun of the bandit 1990s.","fact":"The film assembles a star ensemble of Russian actors, many of them in grotesque criminal roles quite unlike their usual work.","wiki_en":"Dead Man's Bluff"},{"name":"Gorko!","emoji":"🥂","meta":["comedy","2013","Zhora Kryzhovnikov"],"description":"A young couple dreams of a small modern wedding, but the parents insist on a lavish traditional banquet with all the trimmings, and the resulting celebration turns into one excruciating comic disaster after another. The title is the cry guests shout at Russian weddings.","fact":"It is shot to look like amateur footage from a wedding videographer's camera, which gives everything on screen a documentary feel.","wiki_en":"Gorko!"},{"name":"Yolki","emoji":"🎄","meta":["New Year comedy","2010","Timur Bekmambetov and others"],"description":"On New Year's Eve a message for the country's president is passed by word of mouth through a chain of chance acquaintances, while several funny holiday stories unfold in different Russian cities at the same time. This portmanteau film began a long-running annual series.","fact":"The success of the first film led to a whole run of sequels, each released just in time for another New Year.","wiki_en":"Yolki (film)","wiki_ru":"Ёлки (фильм)"},{"name":"The Best Movie","emoji":"🎬","meta":["parody comedy","2008","Kirill Kuzin"],"description":"A parody built as a run of send-ups: the makers work through the clichés of popular Russian films, television series and advertising, replaying well-known scenes in recognisable form. It gathered a starry cast of Russian comics and was a big box-office hit of its year.","fact":"The title and the style parody the Hollywood spoof series such as Scary Movie, adapted to Russian material.","wiki_en":"The Best Movie"},{"name":"Lyubov-Morkov","emoji":"🥕","meta":["comedy","2007","Alexander Strizhenov"],"description":"A married couple worn out with each other after many years unexpectedly swap bodies after a session with a psychic, and each has to live a day in the other's skin. This body-swap comedy became one of the most popular Russian family films of its time.","fact":"Its success produced several sequels, in which the same couple runs into similar magical transformations again.","wiki_en":"Lyubov-Morkov","wiki_ru":"Любовь-морковь"},{"name":"Ivan Tsarevich and the Grey Wolf","emoji":"🐺","meta":["animation","2011","Vladimir Toropchin"],"description":"Ivan, the hapless youngest son of the tsar, sets off with a quick-witted talking Grey Wolf to fetch the Firebird and cure his ailing father, and runs through a string of comic adventures with characters out of folklore. Russian folk tales meet modern humour.","fact":"The success of the first film began a whole series of sequels about Ivan Tsarevich and his wolf companion.","wiki_en":"Ivan Tsarevich and the Gray Wolf (film)","wiki_ru":"Иван Царевич и Серый Волк (мультфильм)"},{"name":"Three Bogatyrs and the Shamakhan Queen","emoji":"🐴","meta":["animation","2010","Sergei Glezin"],"description":"The heroes Ilya Muromets, Dobrynya Nikitich and Alyosha Popovich, along with the endlessly scheming Prince of Kiev, are drawn into a tangle with the cunning Shamakhan Queen, whose spells turn the city's life upside down. One of a popular Russian animated series.","fact":"The films about the three bogatyrs became one of the longest-running and most profitable Russian animation franchises.","wiki_en":"Three Bogatyrs and the Shamakhan Queen","wiki_ru":"Три богатыря и Шамаханская царица"},{"name":"Kholop","emoji":"🎩","meta":["comedy","2019","Klim Shipenko"],"description":"A spoiled rich heir is tricked by his family, after one outrage too many, into a staged nineteenth-century serf village, where he is made to live and work alongside real peasants to teach him some humility. Klim Shipenko's comedy was a huge Russian hit.","fact":"On release it was the highest-grossing Russian film ever in its home cinemas, taking more than three billion roubles.","wiki_en":"Serf (film)","wiki_ru":"Холоп (фильм)"},{"name":"Major Grom: Plague Doctor","emoji":"🦇","meta":["superhero film","2021","Oleg Trofim"],"description":"Igor Grom, an unbending St Petersburg policeman, takes on a mysterious masked vigilante, the Plague Doctor, who is handing out his own justice to the city's corrupt. Adapted from a popular Russian comic, it was one of the first notable domestic superhero films.","fact":"The film is based on a series of Russian comics from the publisher Bubble, running since the early 2010s.","wiki_en":"Major Grom: Plague Doctor"},{"name":"Attraction","emoji":"🛸","meta":["science fiction","2017","Fyodor Bondarchuk"],"description":"After an unidentified craft crashes on the edge of Moscow, panic and aggression spread through the frightened neighbourhood, while an officer's daughter unexpectedly finds common ground with the alien visitor. Bondarchuk's blockbuster mixes spectacle with a drama of fear.","fact":"The crash scenes were shot on large-scale sets built to imitate a real Moscow housing district.","wiki_en":"Attraction (2017 film)"},{"name":"Avatar: The Way of Water","emoji":"🌊","meta":["science fiction","2022","James Cameron"],"description":"Years after the first film, the former marine Jake Sully and his Na'vi family have to leave their forest home and seek shelter among the reef clans of Pandora to escape a new human threat. The sequel widened the planet's underwater world and again transformed 3D.","fact":"For some of the underwater scenes the actors really did hold their breath for long stretches, without scuba gear.","wiki_en":"Avatar: The Way of Water"},{"name":"Deadpool 2","emoji":"⚔️","meta":["superhero film","2018","David Leitch"],"description":"The cynical and hopelessly talkative mutant mercenary Deadpool puts together a superhero team of his own to protect a young mutant from a merciless cyborg soldier arriving from the future. The sequel kept the black humour and the direct address to the audience.","fact":"The film is packed with jokes at the expense of other superhero franchises, including the Marvel, DC and X-Men universes.","wiki_en":"Deadpool 2"},{"name":"Joker: Folie à Deux","emoji":"🃏","meta":["crime drama","2024","Todd Phillips"],"description":"Arthur Fleck, now held in Arkham psychiatric hospital, meets a patient called Harley Quinzel, and the two are drawn together by mutual attraction and a shared contempt for the world outside. The sequel to the Oscar-winning 2019 film turned the villain's origin story into a musical.","fact":"Unlike the first film, a large part of the sequel's story is carried by musical numbers performed by the leads.","wiki_en":"Joker: Folie à Deux"},{"name":"Cruella","emoji":"🐶","meta":["crime drama","2021","Craig Gillespie"],"description":"The back story of the famous Disney villain: Estella, a gifted but unrecognised fashion designer in the punk London of the 1970s, gradually becomes the brazen and vengeful Cruella de Vil. The prequel leans hard on the look of the punk rock era.","fact":"The costumes were made by Jenny Beavan, who won an Oscar for them, drawing on the fashion of London's 1970s punk scene.","wiki_en":"Cruella (film)"},{"name":"Die Hard 2","emoji":"✈️","meta":["action","1990","Renny Harlin"],"description":"The policeman John McClane is once again in the wrong place at the wrong time — this time an airport seized by armed mercenaries who are threatening hundreds of passengers in planes circling overhead. The sequel moved the action from one skyscraper to a whole airport.","fact":"Like the first film, it is set on Christmas Eve, which became a trademark of the whole franchise.","wiki_en":"Die Hard 2"},{"name":"Die Hard with a Vengeance","emoji":"💣","meta":["action","1995","John McTiernan"],"description":"A mysterious terrorist makes the exhausted John McClane solve lethal riddles all over New York, until he realises that the whole ordeal is a distraction from a far bigger crime. The third film brought back the director of the original Die Hard.","fact":"For the first time in the series McClane's partner is a civilian, Zeus, played by Samuel L. Jackson.","wiki_en":"Die Hard with a Vengeance"},{"name":"Men in Black II","emoji":"👽","meta":["science fiction","2002","Barry Sonnenfeld"],"description":"Agent Jay brings his former partner Kay back into service, years after Kay's memory of the job was wiped, so that together they can stop a dangerous new alien hunting for an artefact hidden on Earth. The sequel carries on the comic story of the planet's secret guardians.","fact":"The audience's favourite alien worms are back, with noticeably more screen time than before.","wiki_en":"Men in Black II"},{"name":"Godzilla vs. Kong","emoji":"🦖","meta":["science fiction","2021","Adam Wingard"],"description":"Two legendary giant monsters, the reptilian Godzilla and the enormous ape Kong, meet in an epic fight, while humans try to work out the real reason for Godzilla's sudden aggression. The film brought two big Legendary franchises together in the MonsterVerse.","fact":"For the fight with Godzilla, Kong was grown considerably: in this universe he is far larger than in his own Skull Island film.","wiki_en":"Godzilla vs. Kong"},{"name":"Jurassic World","emoji":"🦕","meta":["science fiction","2015","Colin Trevorrow"],"description":"Two decades after the first Jurassic Park, a fully working dinosaur theme park is running on the island, until the scientists engineer a new hybrid predator that turns out far more dangerous than anyone expected. The reboot was one of the biggest hits of its year.","fact":"It set the record for the biggest opening weekend at the box office at the time of its release in 2015.","wiki_en":"Jurassic World"},{"name":"Don't Look Up","emoji":"☄️","meta":["satirical comedy","2021","Adam McKay"],"description":"Two little-known astronomers discover a comet that will certainly destroy the Earth and try to get through to politicians and media absorbed in their own immediate concerns rather than the coming catastrophe. A star-studded satire on the way society consumes information.","fact":"For all the science fiction premise, the makers intended the film as a metaphor for public indifference to climate change.","wiki_en":"Don't Look Up"},{"name":"Green Book","emoji":"🚗","meta":["drama","2018","Peter Farrelly"],"description":"A rough-edged bouncer from the Bronx takes a job as driver and bodyguard to a refined Black pianist touring the segregated American South of the 1960s, and over the long journey an unlikely friendship grows. It won the Oscar for best picture and is based on a true story.","fact":"The title refers to the real Green Book, a guide that helped Black travellers of the time find places in the South where they were safe.","wiki_en":"Green Book (film)","wiki_ru":"Зелёная книга (фильм)"},{"name":"1917","emoji":"🪖","meta":["war drama","2019","Sam Mendes"],"description":"Two young British soldiers in the First World War are ordered to carry a message calling off an attack to a neighbouring regiment, to save thousands of comrades walking into a German trap. Sam Mendes shot the film to look like one unbroken take almost throughout.","fact":"To sustain the illusion of a continuous shot, the crew rehearsed the hardest moving-camera scenes for many months.","wiki_en":"1917 (2019 film)"},{"name":"The Martian","emoji":"🚀","meta":["science fiction","2015","Ridley Scott"],"description":"An astronaut is left behind on Mars by mistake when his crew evacuates during a dust storm, and has to survive alone on a hostile planet on nothing but scientific knowledge and improvisation until a rescue becomes possible. From Andy Weir's novel, famous for getting the detail right.","fact":"The writers and advisers worked with real NASA specialists to make the hero's survival methods as realistic as possible.","wiki_en":"The Martian (film)"},{"name":"Gravity","emoji":"🛰️","meta":["science fiction","2013","Alfonso Cuarón"],"description":"A storm of debris destroys the shuttle during a spacewalk, and a rookie astronaut is left alone in orbit, fighting to survive in weightlessness as her oxygen runs down. Alfonso Cuarón's film astonished audiences with its long takes and its rendering of space.","fact":"To create the illusion of weightlessness, the actors were placed inside a rig with controlled lighting that mimicked open space.","wiki_en":"Gravity (2013 film)"},{"name":"Scream","emoji":"🔪","meta":["horror","1996","Wes Craven"],"description":"A quiet American town is hit by a string of brutal murders committed by a masked killer who knows the rules of the classic slasher inside out and keeps testing his victims on them. Wes Craven's film revived the slasher by making fun of its own clichés.","fact":"The killer's mask became one of the most recognisable and most reproduced images in pop culture, Halloween costumes included.","wiki_en":"Scream (1996 film)"},{"name":"Halloween","emoji":"🔪","meta":["horror","1978","John Carpenter"],"description":"Years after murdering his sister as a child, the unstable Michael Myers escapes from a mental hospital and comes back to his home town on Halloween night to hunt the local teenagers. John Carpenter's low-budget film is one of the founders of the slasher genre.","fact":"The famously unnerving theme was written by John Carpenter himself and is one of the most recognisable tunes in horror.","wiki_en":"Halloween (1978 film)"},{"name":"Friday the 13th","emoji":"🏕️","meta":["horror","1980","Sean Cunningham"],"description":"A group of young counsellors preparing to reopen a summer camp abandoned after a tragedy are picked off one by one by an unknown killer avenging a child who drowned in that same lake years before. Sean Cunningham's cheap film began a long-running horror franchise.","fact":"Jason Voorhees, the franchise's emblem, barely appears in the first film, and his famous hockey mask only turns up in the third.","wiki_en":"Friday the 13th (1980 film)"},{"name":"A Nightmare on Elm Street","emoji":"🧤","meta":["horror","1984","Wes Craven"],"description":"A burned killer in a red and green striped sweater, with blades instead of fingers, stalks the teenagers of one neighbourhood inside their own dreams, from which his victims cannot wake alive. Wes Craven gave horror one of its most recognisable villains, Freddy Krueger.","fact":"Robert Englund, who played Freddy Krueger, went on playing him in nearly every film and series of the franchise for decades.","wiki_en":"A Nightmare on Elm Street"},{"name":"Saw","emoji":"🩸","meta":["horror","2004","James Wan"],"description":"Two men who have never met wake chained up in a filthy bathroom and find that they are players in the deadly game of a mysterious killer who tests his victims with elaborate moral and physical traps. James Wan's cheap debut began a whole franchise of trap horror.","fact":"It was shot in only eighteen days on an extremely small budget, and still took many times its cost worldwide.","wiki_en":"Saw (2004 film)"},{"name":"It","emoji":"🎈","meta":["horror","2017","Andy Muschietti"],"description":"A group of outcast children in a small American town band together against an ancient evil that takes the shape of their worst fears, most often appearing to them as the sinister clown Pennywise. This adaptation of Stephen King is one of the biggest horror hits ever.","fact":"Bill Skarsgård's Pennywise became one of the most recognisable screen versions of a Stephen King villain.","wiki_en":"It (2017 film)"},{"name":"A Quiet Place","emoji":"🤫","meta":["horror","2018","John Krasinski"],"description":"A family survives in a world overrun by blind creatures with hypersensitive hearing, and has to speak in signs and move in near-total silence to avoid being noticed. John Krasinski built the film on an amount of dialogue and sound unusually small for horror.","fact":"Much of the dialogue is carried in American Sign Language rather than in speech.","wiki_en":"A Quiet Place"},{"name":"The Conjuring","emoji":"🕯️","meta":["horror","2013","James Wan"],"description":"A couple moves into an old farmhouse in Rhode Island where increasingly frightening events drive them to call in the well-known investigators of the paranormal, Ed and Lorraine Warren. James Wan's film is based on one of the Warrens' real cases and began a large horror universe.","fact":"It was rated R not for blood or violence, of which there is almost none, but for the sheer fright of its atmosphere.","wiki_en":"The Conjuring"},{"name":"Insidious","emoji":"👻","meta":["horror","2010","James Wan"],"description":"After their son falls mysteriously into a coma, a family faces ever more frightening events in the house and calls in a medium, who explains it as the boy's connection to an other world called the Further. James Wan's cheap film was one of the most profitable horrors of its time.","fact":"This is where the medium Elise Rainier first appears, later becoming the central figure of the whole franchise, prequels included.","wiki_en":"Insidious (film)"},{"name":"Get Out","emoji":"🌀","meta":["horror thriller","2017","Jordan Peele"],"description":"A young Black photographer goes to the country to meet his white girlfriend's family and notices more and more that is wrong in the behaviour of his hosts and their guests, who are hiding something sinister. The comedian Jordan Peele's debut joined horror to racial satire.","fact":"It won the Oscar for best original screenplay, a rarity for a film that formally belongs to horror.","wiki_en":"Get Out"},{"name":"Chicago","emoji":"🎷","meta":["musical","2002","Rob Marshall"],"description":"A would-be singer and an established vaudeville star, both charged with murder, compete for the public's attention and for a slick lawyer in the jazz-age Chicago of the 1920s, where scandal is a ticket to fame. The Broadway adaptation won best picture and revived the film musical.","fact":"The musical numbers are staged as imaginary performances running in the heroine's mind alongside the real events.","wiki_en":"Chicago (2002 film)"},{"name":"Moulin Rouge!","emoji":"🎭","meta":["musical","2001","Baz Luhrmann"],"description":"A young English poet in bohemian Paris at the end of the nineteenth century falls in love with the star of the famous Moulin Rouge cabaret, and their affair plays out through vivid numbers that fold pop hits into classic melodies. Baz Luhrmann's film is fast, eccentric and gaudy.","fact":"The soundtrack mixes classic operatic parts with covers of modern pop songs from several decades, built into single numbers.","wiki_en":"Moulin Rouge!"},{"name":"Bohemian Rhapsody","emoji":"🎤","meta":["musical biography","2018","Bryan Singer"],"description":"The film follows Queen from their first small club gigs to their standing as one of the greatest rock bands in the world, paying particular attention to the vivid, contradictory figure of their frontman Freddie Mercury. It ends by recreating their set at Live Aid.","fact":"Rami Malek won an Oscar as Freddie Mercury, a part he prepared for at length, studying his stage movement and his singing.","wiki_en":"Bohemian Rhapsody (film)"},{"name":"Rocketman","emoji":"🕶️","meta":["musical biography","2019","Dexter Fletcher"],"description":"A biographical musical about Elton John's road from a shy boy in the London suburbs to one of the most extravagant stars in pop, told through his own famous songs. Unlike many music biopics, it openly mixes real events with fantasy numbers.","fact":"All the vocals in the film were sung by Taron Egerton himself, not by the original performer of the songs.","wiki_en":"Rocketman (film)"},{"name":"Les Misérables","emoji":"🇫🇷","meta":["musical","2012","Tom Hooper"],"description":"The former convict Jean Valjean, having broken his parole, tries to begin an honest new life, but the unbending police inspector Javert will not let him go, and it all plays out against the popular unrest of nineteenth-century Paris. The songs were sung live on set.","fact":"Anne Hathaway won an Oscar as Fantine, and her great song was filmed in a single unbroken close-up.","wiki_en":"Les Misérables (2012 film)"}];
